async function tryDecomposeSelectedPart(){
  if(!sel){setStatus('Nejdřív vyber asset na plátně.');return;}
  if(sel.children){ungroupSelected(); return;}
  const src=getPartImage(sel);
  if(!src){setStatus('Vybraný asset nemá obrázek pro rozklad.');return;}
  const w=src.naturalWidth||src.width, h=src.naturalHeight||src.height;
  const c=document.createElement('canvas'); c.width=w; c.height=h; const x=c.getContext('2d'); x.drawImage(src,0,0,w,h);
  const data=x.getImageData(0,0,w,h).data;
  const vis=new Uint8Array(w*h);
  const comps=[];
  const idx=(xx,yy)=>yy*w+xx;
  const opaque=(xx,yy)=>data[idx(xx,yy)*4+3]>24;
  for(let yy=0;yy<h;yy++)for(let xx=0;xx<w;xx++){
    const id=idx(xx,yy); if(vis[id]||!opaque(xx,yy))continue;
    const q=[[xx,yy]]; vis[id]=1; let minX=xx,maxX=xx,minY=yy,maxY=yy,count=0;
    while(q.length){ const [cx,cy]=q.pop(); count++; if(cx<minX)minX=cx; if(cx>maxX)maxX=cx; if(cy<minY)minY=cy; if(cy>maxY)maxY=cy;
      for(const [nx,ny] of [[cx+1,cy],[cx-1,cy],[cx,cy+1],[cx,cy-1]]){ if(nx<0||ny<0||nx>=w||ny>=h)continue; const ni=idx(nx,ny); if(vis[ni]||!opaque(nx,ny))continue; vis[ni]=1; q.push([nx,ny]); }
    }
    if(count>=18)comps.push({minX,maxX,minY,maxY,count,cx:(minX+maxX)/2,cy:(minY+maxY)/2,w:maxX-minX+1,h:maxY-minY+1});
  }
  if(comps.length<2){ if(/weapon|gun|rifle|ak|pistol|knife|mec|meč/i.test(sel.name||'') || (sel.role||'').startsWith('weapon')){ await tryDecomposeWeaponSelected(); return; } setStatus('Rozklad nic smysluplného nenašel. Zkus asset s průhledným pozadím nebo složený asset.');return;}
  comps.sort((a,b)=>b.count-a.count);
  const imgCx=w/2, imgCy=h/2;
  // role guess
  let head=null, body=null;
  head=[...comps].sort((a,b)=>a.cy-b.cy)[0];
  body=[...comps].sort((a,b)=>b.count-a.count).find(c=>c!==head) || head;
  const midY=(head.cy+body.cy)/2;
  for(const c of comps){
    let role='';
    if(c===head)role='head';
    else if(c===body)role='body';
    else if(c.cy>body.cy+body.h*0.15){ role=(c.cx<imgCx?'footL':'footR'); }
    else if(c.cy>=midY-body.h*0.2 && c.cy<=body.cy+body.h*0.3){ role=(c.cx<imgCx?'handL':'handR'); }
    else if(c.cx>imgCx+body.w*0.12) role='weapon';
    else if(c.cx<imgCx-body.w*0.12) role='handL';
    c.role=role;
  }
  const dispScaleX=sel.w/w, dispScaleY=sel.h/h;
  const newParts=[];
  for(const cpt of comps.slice(0,12)){
    const cc=document.createElement('canvas'); cc.width=cpt.w; cc.height=cpt.h; const cx2=cc.getContext('2d');
    cx2.drawImage(c,cpt.minX,cpt.minY,cpt.w,cpt.h,0,0,cpt.w,cpt.h);
    const dataUrl=cc.toDataURL('image/png'); const im=await loadImageURL(dataUrl);
    const localCx=(cpt.cx - w/2)*dispScaleX, localCy=(cpt.cy - h/2)*dispScaleY;
    const world=localToWorld({x:sel.x,y:sel.y,rot:sel.rot,scale:sel.scale,flipX:sel.flipX},localCx,localCy);
    const p=Object.assign({id:++idCtr,name:(cpt.role||'cast')+'_'+String(idCtr),x:world.x,y:world.y,rot:sel.rot,scale:sel.scale,w:cpt.w*dispScaleX,h:cpt.h*dispScaleY,img:im,kind:'image',visible:true,z:defaultZForRole(cpt.role||''),flipX:sel.flipX,srcData:dataUrl,role:cpt.role||'',category:'decomposed',opacity:1,locked:false,overlayRef:'',overlaySide:'none',pinX:undefined,pinY:undefined,parentId:null,parentOffsetX:0,parentOffsetY:0,attachRot:0,inheritRot:true,pinX:0,pinY:0,parentId:null,parentOffsetX:0,parentOffsetY:0,attachRot:0,inheritRot:true});
    ensurePin(p); newParts.push(p);
  }
  parts=parts.filter(p=>p!==sel); parts.push(...newParts); selectedIds=new Set(newParts.map(p=>p.id)); sel=newParts.length===1?newParts[0]:null; applyAutoLayers('madness'); renderList(); updateProps(); draw(); drawTL(); setStatus('Rozklad hotový. Nalezené části: '+newParts.length+'. Zkus pak PŘIPNOUT K RUCE nebo AUTO DRŽENÍ ZBRANĚ.');
}
function foxyReport(msg){const el=document.getElementById('foxy-report'); if(el)el.textContent=msg; setStatus(msg.split('\n')[0]);}
function foxyAddChat(role,msg){
  const log=document.getElementById('foxy-chat-log'); if(!log)return;
  const d=document.createElement('div'); d.className='foxy-msg '+(role==='user'?'user':'ai'); d.textContent=msg; log.appendChild(d); log.scrollTop=log.scrollHeight;
}
function foxySceneSummary(){
  const counts={};
  for(const p of parts){counts[p.role||'bez_role']=(counts[p.role||'bez_role']||0)+1;}
  const selInfo=sel?('Vybráno: '+sel.name+' ['+(sel.role||'bez role')+']'):'Nic není vybrané.';
  const txtCount=parts.filter(p=>p.kind==='text').length;
  return selInfo+'\nČástí ve scéně: '+parts.length+'\nTextových assetů: '+txtCount+'\nRole: '+Object.entries(counts).map(([k,v])=>k+': '+v).join(', ');
}
function foxyCasualReply(q){
  if(/ahoj|cau|čau|cus|nazdar/.test(q))return 'Čau, jsem tvoje offline Foxy AI. Klidně si se mnou piš normálně. Umím i dělat akce v editoru, když mi napíšeš příkaz.';
  if(/jak se mas|jak se máš|co delas|co děláš/.test(q))return 'Mám se dobře :-) Běžím offline přímo v editoru. Vidím aktuální scénu, role assetů a umím pomáhat s animací.';
  if(/kdo jsi|co jsi/.test(q))return 'Jsem Foxy AI — offline pomocník pro tenhle editor. Umím rozpoznávat assety, radit s animací, rozkládat postavy a zbraně, připínat assety a dělat základní animace.';
  if(/jak udelam|jak udělam|jak delat|jak dělat/.test(q) && /hod/.test(q))return 'Pro hod: 1) měj ruku a zbraň zvlášť, 2) připni zbraň k ruce, 3) napiš mi udělej hod, 4) pak doladíš jednotlivé snímky v časové ose.';
  if(/jak udelam|jak udělam|jak delat|jak dělat/.test(q) && /sek|mec|meč/.test(q))return 'Pro sek: 1) ruka + meč zvlášť, 2) připnout meč k ruce, 3) použít udělej sek, 4) potom upravit snímky.';
  if(/dik|dík|dekuju|děkuju/.test(q))return 'Není zač. Když budeš chtít, můžu rovnou něco udělat se scénou.';
  return '';
}
function foxyNormalize(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
async function foxyRunCommand(raw){
  const q=foxyNormalize(raw);
  if(!q.trim())return;
  foxyAddChat('user',raw);
  let answer='';
  try{
    const casual=foxyCasualReply(q);
    const quoted=(raw.match(/[\"“](.*?)[\"”]/)||[])[1]||'';
    if(casual){
      answer=casual;
    }else if(/pomoc|help|co umis|prikazy/.test(q)){
      answer='Umím offline příkazy: poznat role, rozlož zbraň, rozlož postavu, připni zbraň k ruce, odepnout, udělej hod, udělej sek, udělej úder, idle, nauč se role, použij naučené, stav scény, ai náhled, přidej text.';
    }else if(/stav|scena|scene|co mam/.test(q)){
      answer=foxySceneSummary();
    }else if(/(vypn|skryj).*(nahled|náhled)|schovej.*(nahled|náhled)/.test(q)){
      foxyVisionPreview=false; draw(); answer='FOXY AI: Náhled vypnutý.';
    }else if(/nahled|náhled|preview|jak vidi ai|jak to vidi/.test(q)){
      foxyVisionPreview=true; draw(); answer='FOXY AI: Náhled zapnutý. Zelené čtverečky a popisky jsou jen náhled.';
    }else if(/pridej text|přidej text|vloz text|vlož text|napis text|napiš text/.test(q)){
      if(quoted){ await addTextPart(quoted,{name:'TEXT',fontSize:42,textColor:'#ffffff'}); answer='FOXY AI: Přidal jsem text: '+quoted; }
      else{ openTextModal(''); answer='FOXY AI: Otevřel jsem okno pro vložení textu. Když chceš, můžeš mi napsat třeba: přidej text "BANG!"'; }
    }else if(/pozn|analyz|role|hlava|ruka|noha/.test(q)){
      foxyAnalyzeSelected(); answer=document.getElementById('foxy-report')?.textContent||'Role zkontrolované.';
    }else if(/rozloz.*(zbran|ak|weapon|gun|rifle|pistol)|zasobnik|hlaven|pazba|pažba/.test(q)){
      await tryDecomposeWeaponSelected(); answer=document.getElementById('foxy-report')?.textContent||'Zkusil jsem rozložit zbraň.';
    }else if(/rozloz|rozebrat|rozdel|postav|gif|obrazek/.test(q)){
      await tryDecomposeSelectedPart(); answer=document.getElementById('foxy-report')?.textContent||'Zkusil jsem rozložit obrázek.';
    }else if(/pripn|připn|drz|drž|ruc|ruce|ruku|auto.*zbran/.test(q)){
      autoAttachWeaponMadness(); answer=document.getElementById('foxy-report')?.textContent||'Zkusil jsem připnout zbraň k ruce.';
    }else if(/odepn|odpoj/.test(q)){
      detachSelectedParent(); answer=document.getElementById('foxy-report')?.textContent||'Odepnuto.';
    }else if(/hod|throw/.test(q)){
      foxyThrowAnim(); answer=document.getElementById('foxy-report')?.textContent||'Vytvořil jsem hod.';
    }else if(/sek|slash|mec|melee/.test(q)){
      foxySlashAnim(); answer=document.getElementById('foxy-report')?.textContent||'Vytvořil jsem sek.';
    }else if(/uder|úder|punch|hit|rana/.test(q)){
      foxyPunchAnim(); answer=document.getElementById('foxy-report')?.textContent||'Vytvořil jsem úder.';
    }else if(/idle|dych|dých|klid/.test(q)){
      foxyIdleAnim(); answer=document.getElementById('foxy-report')?.textContent||'Vytvořil jsem idle.';
    }else if(/nauc|nauč|uc se|uč se|zapamatuj/.test(q)){
      teachFoxyFromScene(); answer=document.getElementById('foxy-report')?.textContent||'Naučil jsem se aktuální role.';
    }else if(/pouzij.*nauc|použij.*nauč|aplikuj|pameti|paměti/.test(q)){
      applyFoxyMemoryToScene(); answer=document.getElementById('foxy-report')?.textContent||'Použil jsem naučené role.';
    }else if(/smaz.*nauc|reset.*foxy|zapomen/.test(q)){
      clearFoxyMemory(); answer=document.getElementById('foxy-report')?.textContent||'Foxy učení smazané.';
    }else{
      answer='Jsem offline Foxy AI, takže si s tebou klidně povídám normálně, ale zároveň umím hlavně pomáhat s editorem. Zkus třeba: jak udělám hod zbraně, rozlož zbraň, ai náhled, přidej text "BANG!", připni zbraň k ruce nebo stav scény.\n\n'+foxySceneSummary();
    }
  }catch(err){console.error(err);answer='Foxy narazil na chybu: '+(err&&err.message?err.message:err)+'. Zkus vybrat asset a příkaz zopakovat.';}
  foxyAddChat('ai',answer);
}
function setupFoxyChat(){
  const input=document.getElementById('foxy-chat-input'),send=document.getElementById('foxy-chat-send');
  if(!input||!send)return;
  if(!document.getElementById('foxy-chat-log')?.children.length)foxyAddChat('ai','Čau, jsem Foxy AI offline. Můžeš si se mnou normálně povídat a zároveň mi dávat příkazy do editoru. Zkus třeba: jak udělám hod zbraně, rozlož zbraň, ai náhled nebo přidej text "BANG!".');
  send.onclick=()=>{const v=input.value.trim();input.value='';foxyRunCommand(v);};
  input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();send.click();}});
  document.querySelectorAll('[data-foxy]').forEach(b=>b.onclick=()=>foxyRunCommand(b.dataset.foxy));
}

function getFoxyMemory(){try{return JSON.parse(safeStorageGet(FOXY_AI_KEY)||'{}')||{};}catch(e){return {};}}
function setFoxyMemory(m){safeStorageSet(FOXY_AI_KEY,JSON.stringify(m||{}));}
function teachFoxyFromScene(){
  const mem=getFoxyMemory();
  const items=(selectedIds&&selectedIds.size?parts.filter(p=>selectedIds.has(p.id)):(sel?[sel]:[]));
  if(!items.length){foxyReport('FOXY AI: Nejdřív vyber část nebo víc částí, které chceš naučit.');return;}
  let count=0;
  for(const p of items){ if(!p.name)continue; mem[p.name.toLowerCase()]={role:p.role||guessRoleFromName(p.name,p.category||''), category:p.category||'', decompose:(/weapon|ak|gun|rifle|pistol|knife|meč|mec/i.test(p.name)?'weapon':'character')}; count++; }
  setFoxyMemory(mem);
  foxyReport('FOXY AI: Naučení uložené. Počet záznamů: '+count+'.\nFoxy si bude pamatovat názvy a role těchto assetů.');
}
function applyFoxyMemoryToScene(){
  const mem=getFoxyMemory(); let count=0;
  for(const p of parts){ const nm=(p.name||'').toLowerCase(); for(const k in mem){ if(nm===k || nm.includes(k) || k.includes(nm)){ if(mem[k].role){ p.role=mem[k].role; p.z=defaultZForRole(p.role); count++; break; } } } }
  renderList(); updateProps(); draw();
  foxyReport('FOXY AI: Na scénu byly použité naučené role. Změněno částí: '+count+'.');
}
function clearFoxyMemory(){ setFoxyMemory({}); foxyReport('FOXY AI: Naučení bylo smazané.'); }
function findRolePart(role){ return parts.find(p=>p.role===role) || null; }
function trimRectFromCanvas(can,rect){
  const ctx=can.getContext('2d'); const data=ctx.getImageData(rect.x,rect.y,rect.w,rect.h).data;
  let minX=rect.w,minY=rect.h,maxX=-1,maxY=-1,count=0;
  for(let y=0;y<rect.h;y++)for(let x=0;x<rect.w;x++){ const a=data[(y*rect.w+x)*4+3]; if(a>20){ count++; if(x<minX)minX=x; if(y<minY)minY=y; if(x>maxX)maxX=x; if(y>maxY)maxY=y; } }
  if(count<12||maxX<0||maxY<0)return null;
  return {x:rect.x+minX,y:rect.y+minY,w:maxX-minX+1,h:maxY-minY+1,count};
}
async function createPartFromSourceCrop(src,basePart,rect,name,role,extra={}){
  const sw=src.naturalWidth||src.width, sh=src.naturalHeight||src.height;
  const temp=document.createElement('canvas'); temp.width=sw; temp.height=sh; const tctx=temp.getContext('2d'); tctx.drawImage(src,0,0,sw,sh);
  const trimmed=trimRectFromCanvas(temp,rect); if(!trimmed)return null;
  const cc=document.createElement('canvas'); cc.width=trimmed.w; cc.height=trimmed.h; const cctx=cc.getContext('2d'); cctx.drawImage(temp,trimmed.x,trimmed.y,trimmed.w,trimmed.h,0,0,trimmed.w,trimmed.h);
  const url=cc.toDataURL('image/png'); const im=await loadImageURL(url);
  const dispScaleX=basePart.w/sw, dispScaleY=basePart.h/sh;
  const localCx=((trimmed.x+trimmed.w/2) - sw/2)*dispScaleX;
  const localCy=((trimmed.y+trimmed.h/2) - sh/2)*dispScaleY;
  const world=localToWorld({x:basePart.x,y:basePart.y,rot:basePart.rot,scale:basePart.scale,flipX:basePart.flipX},localCx,localCy);
  const np=Object.assign({id:++idCtr,name,role,x:world.x,y:world.y,rot:basePart.rot,scale:basePart.scale,w:trimmed.w*dispScaleX,h:trimmed.h*dispScaleY,img:im,kind:'image',visible:true,z:defaultZForRole(role),flipX:basePart.flipX,srcData:url,category:basePart.category||'',opacity:1,locked:false,overlayRef:'',overlaySide:'none',pinX:0,pinY:0,parentId:null,parentOffsetX:0,parentOffsetY:0,attachRot:0,inheritRot:true},extra);
  ensurePin(np); return np;
}
async function tryDecomposeWeaponSelected(){
  if(!sel){foxyReport('FOXY AI: Nejdřív vyber zbraň na plátně.');return;}
  const src=getPartImage(sel); if(!src){foxyReport('FOXY AI: Vybraný asset nemá obrázek.');return;}
  const sw=src.naturalWidth||src.width, sh=src.naturalHeight||src.height;
  const zones=[
    {name:'pažba',role:'weaponStock',x:0.00,y:0.20,w:0.28,h:0.40},
    {name:'tělo_zbraně',role:'weapon',x:0.24,y:0.18,w:0.40,h:0.44},
    {name:'rukojeť',role:'weaponGrip',x:0.37,y:0.42,w:0.18,h:0.42},
    {name:'zásobník',role:'weaponMag',x:0.45,y:0.40,w:0.24,h:0.50},
    {name:'hlaveň',role:'weaponBarrel',x:0.58,y:0.22,w:0.42,h:0.18},
    {name:'ústí',role:'muzzle',x:0.91,y:0.18,w:0.09,h:0.18}
  ];
  const created=[];
  for(const z of zones){ const part=await createPartFromSourceCrop(src,sel,{x:Math.max(0,Math.floor(sw*z.x)),y:Math.max(0,Math.floor(sh*z.y)),w:Math.max(2,Math.floor(sw*z.w)),h:Math.max(2,Math.floor(sh*z.h))}, (sel.name||'zbran')+'_'+z.name, z.role); if(part)created.push(part); }
  if(created.length<2){ foxyReport('FOXY AI: Rozklad zbraně nic nenašel. Zkus průhledné PNG nebo větší asset.'); return; }
  const root=created.find(p=>p.role==='weapon') || created[0];
  for(const p of created){ if(p!==root){ p.parentId=root.id; updateAttachmentFromWorld(p); } }
  parts=parts.filter(p=>p!==sel); parts.push(...created); selectedIds=new Set(created.map(p=>p.id)); sel=root; syncAllParentedParts(); renderList(); updateProps(); draw(); drawTL();
  foxyReport('FOXY AI: Zbraň byla rozložená na části. Vzniklo částí: '+created.length+'.\nTeď můžeš třeba připnout celé tělo zbraně k pravé ruce a ostatní kusy se povezou s ním.');
}
function foxyAnalyzeSelected(){
  const target=sel || (parts.length===1?parts[0]:null);
  if(!target){foxyReport('FOXY AI: Vyber asset nebo část, kterou chceš analyzovat.'); return;}
  const guessed=guessRoleFromName(target.name,target.category||'')||target.role||'neurčeno';
  if(!target.role)target.role=guessed;
  if(/weapon|gun|rifle|ak|pistol|meč|mec|knife/i.test(target.name)||target.role.startsWith('weapon')){
    foxyReport('FOXY AI analýza:\n• vypadá to jako ZBRAŇ\n• doporučení: použij AI ROZLOŽIT ZBRAŇ / AK\n• potom použij AI AUTO DRŽENÍ ZBRANĚ');
  }else{
    foxyReport('FOXY AI analýza:\n• odhadnutá role: '+target.role+'\n• doporučení: použij AI ROZLOŽIT POSTAVU / OBRÁZEK\n• pak zkontroluj role a dej AUTO VRSTVY');
  }
  target.z=defaultZForRole(target.role); renderList(); updateProps(); draw();
}
function buildFramesFromPoses(poses,label){ frames=poses; curF=0; applyFrame(0); draw(); drawTL(); updateProps(); foxyReport('FOXY AI: Hotovo — vytvořená animace '+label+' se '+poses.length+' snímky.'); }
function clonePose(base){ return JSON.parse(JSON.stringify(base)); }
function foxyIdleAnim(){ if(!parts.length){foxyReport('FOXY AI: Není co animovat.'); return;} const base=currentPose(); const p1=clonePose(base), p2=clonePose(base), p3=clonePose(base), p4=clonePose(base); for(const id in p2){ if((p2[id].role||'')==='body'){ p2[id].y-=3; p3[id].y-=1; } if((p2[id].role||'')==='head'){ p2[id].y-=2; p3[id].y-=1; } } buildFramesFromPoses([p1,p2,p3,p4,p1],'IDLE / dýchání'); }
