function foxyPunchAnim(){ if(!parts.length){foxyReport('FOXY AI: Není co animovat.'); return;} const base=currentPose(); const a=clonePose(base), b=clonePose(base), c=clonePose(base), d=clonePose(base), e=clonePose(base); withRolePose(b,'handR',p=>{p.x-=20; p.y-=6; p.rot-=0.35;}); withRolePose(c,'handR',p=>{p.x+=42; p.y-=8; p.rot+=0.15;}); withRolePose(d,'handR',p=>{p.x+=18; p.y-=3;}); withRolePose(b,'body',p=>{p.rot-=0.08;}); withRolePose(c,'body',p=>{p.rot+=0.05;}); buildFramesFromPoses([a,b,c,d,e],'ÚDER'); }
function foxySlashAnim(){ if(!parts.length){foxyReport('FOXY AI: Není co animovat.'); return;} const base=currentPose(); const a=clonePose(base), b=clonePose(base), c=clonePose(base), d=clonePose(base), e=clonePose(base); withRolePose(b,'handR',p=>{p.x-=18; p.y-=18; p.rot-=0.6;}); withRolePose(c,'handR',p=>{p.x+=30; p.y+=8; p.rot+=0.9;}); withRolePose(d,'handR',p=>{p.x+=10; p.y+=2; p.rot+=0.2;}); withRolePose(b,'weapon',p=>{p.rot-=0.6;}); withRolePose(c,'weapon',p=>{p.rot+=0.9;}); buildFramesFromPoses([a,b,c,d,e],'SEK / melee'); }
function foxyThrowAnim(){ if(!parts.length){foxyReport('FOXY AI: Není co animovat.'); return;} const base=currentPose(); const a=clonePose(base), b=clonePose(base), c=clonePose(base), d=clonePose(base), e=clonePose(base), f=clonePose(base); withRolePose(b,'handR',p=>{p.x-=18; p.y-=10; p.rot-=0.5;}); withRolePose(c,'handR',p=>{p.x+=26; p.y-=18; p.rot+=0.35;}); let weaponIds=[]; for(const id in base){ if((base[id].role||'').startsWith('weapon')|| (base[id].role||'')==='muzzle') weaponIds.push(id); } for(const wid of weaponIds){ d[wid].parentId=null; d[wid].x+=60; d[wid].y-=24; d[wid].rot+=0.8; e[wid].parentId=null; e[wid].x+=125; e[wid].y-=42; e[wid].rot+=1.35; f[wid].parentId=null; f[wid].x+=175; f[wid].y-=34; f[wid].rot+=1.8; } buildFramesFromPoses([a,b,c,d,e,f],'HOD'); }
function applyAutoLayers(mode='madness'){
  for(const p of parts){
    if(!p.role)p.role=guessRoleFromName(p.name,p.category||'');
    if(mode==='bodyHead'){if(p.role==='footL'||p.role==='footR')p.z=5;if(p.role==='body')p.z=20;if(p.role==='head')p.z=45;}
    else if(mode!=='manual')p.z=defaultZForRole(p.role);
    applyOverlayRuleToPart(p);
  }
  renderList();updateProps();draw();drawTL();setStatus('Vrstvy nastavené: boty < body < ruce < hlava < zbraň/efekty.');
}
function duplicatePart(){
  if(!sel)return;
  const p=sel;
  const copy=Object.assign({},p,{id:++idCtr,name:p.name+'_copy',x:p.x+18,y:p.y+18,z:p.z+1,img:p.img,frames:p.frames||null});
  parts.push(copy);selectPart(copy);drawTL();setStatus('Part duplikovaný.');
}
function resetPart(){if(!sel)return;sel.rot=0;sel.scale=1;sel.opacity=1;sel.flipX=false;updateProps();draw();setStatus('Transform resetovaný.');}
function centerPart(){if(!sel)return;sel.x=W/2;sel.y=H/2;updateProps();draw();setStatus('Part vycentrovaný.');}
function flipPart(){if(!sel)return;sel.flipX=!sel.flipX;updateProps();draw();setStatus('Part zrcadlený přes X.');}
function hidePart(){if(!sel)return;sel.visible=sel.visible===false?true:false;renderList();draw();setStatus(sel.visible===false?'Část skrytá.':'Část zobrazená.');}
function rotatePartStep(rad){if(!sel||sel.locked)return;sel.rot+=rad;updateProps();draw();setStatus('Rotace upravená.');}
function scalePartStep(delta){if(!sel||sel.locked)return;sel.scale=Math.max(.03,Math.min(10,sel.scale+delta));updateProps();draw();setStatus('Velikost upravená.');}
function snapSelectedToGrid(size=10){if(!sel||sel.locked)return;sel.x=Math.round(sel.x/size)*size;sel.y=Math.round(sel.y/size)*size;updateProps();draw();setStatus('Část přichycená k mřížce '+size+' px.');}
function centerWholeCharacter(){if(!parts.length)return;let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const p of parts){if(!p.visible)continue;const hw=p.w*p.scale/2,hh=p.h*p.scale/2;minX=Math.min(minX,p.x-hw);maxX=Math.max(maxX,p.x+hw);minY=Math.min(minY,p.y-hh);maxY=Math.max(maxY,p.y+hh);}const dx=W/2-(minX+maxX)/2,dy=H/2-(minY+maxY)/2;for(const p of parts){if(!p.locked){p.x+=dx;p.y+=dy;}}updateProps();draw();setStatus('Celá postava vycentrovaná.');}
function moveLayer(delta){if(!sel)return;sel.z+=delta;updateProps();renderList();draw();}
function sendLayer(top){if(!sel)return;const zs=parts.map(p=>p.z);sel.z=top?Math.max(0,...zs)+1:Math.min(0,...zs)-1;updateProps();renderList();draw();}

function addImagePart(name,img,kind='image',extra={}){
  const maxH=110, ratio=img.width/img.height;
  const h=Math.min(img.height,maxH), w=h*ratio;
  const mem=getFoxyMemory(); const memKey=Object.keys(mem).find(k=>(name||'').toLowerCase()===k || (name||'').toLowerCase().includes(k)); const learnedRole=memKey&&mem[memKey]?mem[memKey].role:''; const guessedRole=extra.role||learnedRole||guessRoleFromName(name,extra.category||'');
  const p=Object.assign({id:++idCtr,name,x:W/2,y:H/2,rot:0,scale:1,w,h,img,kind,visible:true,z:defaultZForRole(guessedRole),flipX:false,srcData:null,role:guessedRole,category:extra.category||'',opacity:1,locked:false,overlayRef:'',overlaySide:'none',pinX:undefined,pinY:undefined,parentId:null,parentOffsetX:0,parentOffsetY:0,attachRot:0,inheritRot:true},extra);
  parts.push(p);selectPart(p);renderList();draw();drawTL();return p;
}

function addGifPart(name,frameImgs){
  if(!frameImgs.length)return;
  const first=frameImgs[0];
  const maxH=120, ratio=first.width/first.height;
  const h=Math.min(first.height,maxH), w=h*ratio;
  const mem=getFoxyMemory(); const memKey=Object.keys(mem).find(k=>(name||'').toLowerCase()===k || (name||'').toLowerCase().includes(k)); const learnedRole=memKey&&mem[memKey]?mem[memKey].role:''; const guessedRole=learnedRole||guessRoleFromName(name,'');
  const p={id:++idCtr,name,x:W/2,y:H/2,rot:0,scale:1,w,h,img:first,kind:'gif',frames:frameImgs.map(img=>({img})),visible:true,z:defaultZForRole(guessedRole),flipX:false,srcData:null,role:guessedRole,opacity:1,locked:false,overlayRef:'',overlaySide:'none',pinX:undefined,pinY:undefined,parentId:null,parentOffsetX:0,parentOffsetY:0,attachRot:0,inheritRot:true};
  parts.push(p);selectPart(p);renderList();draw();drawTL();return p;
}

function selectPart(p){if(p)ensurePin(p);sel=p;selectedIds=new Set(p?[p.id]:[]);allSelected=false;renderList();updateProps();draw();}
function delPart(){if(!sel)return;const deadId=sel.id;parts=parts.filter(p=>p.id!==deadId);for(const p of parts){if(p.parentId===deadId)p.parentId=null;}sel=null;renderList();updateProps();draw();drawTL();setStatus('Part smazán.');}
document.getElementById('btn-delpart').onclick=delPart;

function hitTest(mx,my){
  for(const p of [...sortedParts()].reverse()){
    if(!p.visible)continue;
    const dx=mx-p.x,dy=my-p.y,c=Math.cos(-p.rot),s=Math.sin(-p.rot);
    const lx=c*dx-s*dy,ly=s*dx+c*dy,hw=p.w/2*p.scale,hh=p.h/2*p.scale;
    if(lx>=-hw&&lx<=hw&&ly>=-hh&&ly<=hh)return p;
  }
  return null;
}

let drag=null;
function getMouse(e){const r=MC.getBoundingClientRect(),t=e.touches?e.touches[0]:e;const sx=MC.width/Math.max(1,r.width);const sy=MC.height/Math.max(1,r.height);return{x:(t.clientX-r.left)*sx,y:(t.clientY-r.top)*sy};}
function getCanvasPointFromClient(clientX,clientY){const r=MC.getBoundingClientRect();const sx=MC.width/Math.max(1,r.width);const sy=MC.height/Math.max(1,r.height);return{x:(clientX-r.left)*sx,y:(clientY-r.top)*sy};}
async function addPackAssetAt(asset,x,y){
  if(!asset)return;
  if((asset.category||'')==='mapy'){
    setStatus('Mapy se už nepoužívají, TEST 2D byl odstraněný.');
    return;
  }
  const im=await loadImageURL(asset.path);
  const part=addImagePart(asset.name||'asset',im,'image',{srcData:null,category:asset.category||''});
  part.x=x;part.y=y;selectPart(part);draw();drawTL();
  setStatus('Asset vložen na plátno: '+(asset.name||'asset'));
}
function startDrag(e){
  hideCtxMenu();
  if(playing)stopPlayback();
  const m=getMouse(e);
  if(tool==='draw'||tool==='eraser'){
    paintStroke={mode:tool==='eraser'?'erase':'draw',color:'#ff2020',size:tool==='eraser'?22:7,points:[m]};paintStrokes.push(paintStroke);draw();return;
  }
  const hit=hitTest(m.x,m.y);
  if(aiCropMode){rectSelect={x0:m.x,y0:m.y,x1:m.x,y1:m.y};document.body.classList.add('rect-selecting');draw();return;}
  if(hit){selectPart(hit);if(!hit.locked){drag={p:hit,sx:m.x,sy:m.y,ox:hit.x,oy:hit.y,orot:hit.rot,os:hit.scale};document.body.classList.add('dragging');recordPoseNow(true);}else setStatus('Část je zamčená. Odemkni ji v panelu.');}
  else if(tool==='select'||composeMode){rectSelect={x0:m.x,y0:m.y,x1:m.x,y1:m.y};selectedIds=new Set();sel=null;allSelected=false;document.body.classList.add('rect-selecting');draw();}
  else{sel=null;selectedIds=new Set();renderList();updateProps();draw();}
}
function doDrag(e){
  const m=getMouse(e);
  if(paintStroke){paintStroke.points.push(m);draw();return;}
  if(rectSelect){rectSelect.x1=m.x;rectSelect.y1=m.y;draw();return;}
  if(!drag||drag.p.locked)return;
  const dx=m.x-drag.sx,dy=m.y-drag.sy;if(tool==='rotate')drag.p.rot=drag.orot+dx*.013;else if(tool==='scale')drag.p.scale=Math.max(.05,drag.os+(dx+dy)*.006);else{drag.p.x=drag.ox+dx;drag.p.y=drag.oy+dy;} if(drag.p.parentId)updateAttachmentFromWorld(drag.p); syncAllParentedParts(); draw();updateProps();recordPoseNow(false);
}
function finishRectSelect(){
  if(!rectSelect)return;
  const x1=Math.min(rectSelect.x0,rectSelect.x1),x2=Math.max(rectSelect.x0,rectSelect.x1),y1=Math.min(rectSelect.y0,rectSelect.y1),y2=Math.max(rectSelect.y0,rectSelect.y1);
  const moved=(Math.abs(rectSelect.x1-rectSelect.x0)>4||Math.abs(rectSelect.y1-rectSelect.y0)>4);
  rectSelect=null;document.body.classList.remove('rect-selecting');
  if(!moved){selectedIds=new Set();sel=null;renderList();updateProps();draw();return;}
  if(aiCropMode){const target=aiCropTarget||sel; aiCropMode=false; aiCropTarget=null; if(target){selectedIds=new Set([target.id]);sel=target;renderList();updateProps();draw(); aiCropPartByRect(target,x1,y1,x2,y2);} else setStatus('AI ořez: není vybraný žádný asset.'); return;}
  selectedIds=new Set(parts.filter(p=>p.visible!==false&&partIntersectsRect(p,x1,y1,x2,y2)).map(p=>p.id));
  const selected=parts.filter(p=>selectedIds.has(p.id));sel=selected.length===1?selected[0]:null;allSelected=false;renderList();updateProps();draw();
  if(composeMode){composeMode=false;document.body.classList.remove('compose-mode');if(selectedIds.size){groupSelectedParts();}else setStatus('Nic nebylo označeno pro složení.');}
  else setStatus('Označeno částí: '+selectedIds.size+'. Pravým tlačítkem můžeš složit vybrané části.');
}
function partIntersectsRect(p,x1,y1,x2,y2){const hw=p.w*p.scale/2,hh=p.h*p.scale/2;return !(p.x+hw<x1||p.x-hw>x2||p.y+hh<y1||p.y-hh>y2);}
MC.addEventListener('mousedown',startDrag);
MC.addEventListener('contextmenu',e=>{e.preventDefault();const m=getMouse(e);const hit=hitTest(m.x,m.y);if(hit)selectPart(hit);ctxTarget=hit||null;showCtxMenu(e.clientX,e.clientY,ctxTarget);});
MC.addEventListener('touchstart',e=>{e.preventDefault();startDrag(e)},{passive:false});
window.addEventListener('mousemove',doDrag);
window.addEventListener('touchmove',e=>{if(drag||rectSelect){e.preventDefault();doDrag(e)}},{passive:false});
window.addEventListener('mouseup',()=>{if(paintStroke){paintStroke=null;draw();}if(rectSelect)finishRectSelect();if(drag){recordPoseNow(true);}drag=null;document.body.classList.remove('dragging');});
window.addEventListener('touchend',()=>{if(paintStroke){paintStroke=null;draw();}if(rectSelect)finishRectSelect();if(drag){recordPoseNow(true);}drag=null;document.body.classList.remove('dragging');});
MC.addEventListener('wheel',e=>{if(!sel||sel.locked)return;e.preventDefault();if(e.shiftKey){sel.rot+=(-e.deltaY)*0.002;}else{sel.scale=Math.max(0.03,Math.min(10,sel.scale+(-e.deltaY)*0.0015));}updateProps();draw();},{passive:false});
MC.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';});
MC.addEventListener('drop',async e=>{e.preventDefault();let raw=e.dataTransfer.getData('application/x-foxy-asset')||e.dataTransfer.getData('text/plain');if(!raw)return;let asset=null;try{asset=JSON.parse(raw);}catch(err){asset=PACK_ASSETS.find(a=>a.path===raw||a.name===raw)||null;}if(!asset)return;const m=getCanvasPointFromClient(e.clientX,e.clientY);await addPackAssetAt(asset,m.x,m.y);});

function renderList(){
  const el=document.getElementById('parts-list');el.innerHTML='';
  for(const p of [...parts].reverse()){
    const d=document.createElement('div');d.className='pi'+(sel&&p.id===sel.id?' sel':'');
    d.innerHTML='<span class="dot"></span><span class="pname"></span><span class="eye"></span>';
    d.querySelector('.pname').textContent=(p.locked?'🔒 ':'')+p.name+(p.role?' ['+p.role+']':'')+(p.parentId?' ⤴':'')+(p.overlayRef&&p.overlaySide&&p.overlaySide!=='none'?' {'+(p.overlaySide==='over'?'před ':'za ')+p.overlayRef+'}':'')+' z:'+p.z;
    d.querySelector('.pname').onclick=()=>selectPart(p);
    const eye=d.querySelector('.eye');eye.textContent=p.visible?'👁':'○';
    eye.onclick=ev=>{ev.stopPropagation();p.visible=!p.visible;renderList();draw();};
    el.appendChild(d);
  }
}

function updateProps(){
  const form=document.getElementById('prop-form'),empty=document.getElementById('prop-empty');
  if(!sel){form.style.display='none';empty.style.display='block';return;}
  form.style.display='block';empty.style.display='none';
  document.getElementById('p-name').value=sel.name;
  document.getElementById('p-text').value=sel.text||'';
  document.getElementById('p-fontsize').value=sel.fontSize||42;
  document.getElementById('p-textcolor').value=sel.textColor||'#ffffff';
  document.getElementById('p-text-wrap').style.display=(sel.kind==='text'?'block':'none');
  document.getElementById('p-font-wrap').style.display=(sel.kind==='text'?'block':'none');
  document.getElementById('p-textcolor-wrap').style.display=(sel.kind==='text'?'block':'none');
  document.getElementById('p-x').value=Math.round(sel.x);
  document.getElementById('p-y').value=Math.round(sel.y);
  document.getElementById('p-rot').value=+(sel.rot*180/Math.PI).toFixed(1);
  document.getElementById('p-scale').value=sel.scale;
  document.getElementById('p-z').value=sel.z;
  document.getElementById('p-flipx').checked=!!sel.flipX;
  document.getElementById('p-role').value=sel.role||'';
  document.getElementById('p-overlay-ref').value=sel.overlayRef||'';
  document.getElementById('p-overlay-side').value=sel.overlaySide||'none';
  fillParentSelect(sel); ensurePin(sel);
  document.getElementById('p-parent').value=sel.parentId?String(sel.parentId):'';
  document.getElementById('p-parentdx').value=Math.round(sel.parentOffsetX||0);
  document.getElementById('p-parentdy').value=Math.round(sel.parentOffsetY||0);
  document.getElementById('p-pinx').value=Math.round(sel.pinX||0);
  document.getElementById('p-piny').value=Math.round(sel.pinY||0);
  document.getElementById('p-opacity').value=(sel.opacity===undefined?1:sel.opacity);
  document.getElementById('p-locked').checked=!!sel.locked;
}
