document.getElementById('p-piny').oninput=e=>{if(sel){sel.pinY=+e.target.value; syncAllParentedParts(); updateProps(); draw();}};
document.getElementById('p-opacity').oninput=e=>{if(sel){sel.opacity=+e.target.value;draw();}};
document.getElementById('p-locked').onchange=e=>{if(sel){sel.locked=e.target.checked;renderList();draw();}};
