function setTool(t){tool=t;['select','rotate','scale','draw-tool','eraser-tool'].forEach(x=>{const el=document.getElementById('btn-'+x);if(el)el.classList.remove('active');});const btnId=t==='draw'?'btn-draw-tool':t==='eraser'?'btn-eraser-tool':'btn-'+t;document.getElementById(btnId)?.classList.add('active');document.body.classList.remove('tool-select','tool-rotate','tool-scale','tool-draw','tool-eraser');document.body.classList.add('tool-'+t);}
document.getElementById('btn-select').onclick=()=>setTool('select');
document.getElementById('btn-rotate').onclick=()=>setTool('rotate');
document.getElementById('btn-scale').onclick=()=>setTool('scale');
document.getElementById('btn-draw-tool').onclick=()=>setTool(tool==='draw'?'select':'draw');
document.getElementById('btn-eraser-tool').onclick=()=>setTool(tool==='eraser'?'select':'eraser');
document.getElementById('btn-record').onclick=toggleRecording;
document.getElementById('madness-toggle').onclick=()=>{const p=document.getElementById('madness-panel');const on=p.classList.toggle('mad-min');document.getElementById('madness-toggle').textContent=on?'▶':'▼';};

document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{
  document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');
  document.getElementById('tab-parts').classList.toggle('hidden',b.dataset.tab!=='parts');
  document.getElementById('tab-assets').classList.toggle('hidden',b.dataset.tab!=='assets');
});

function saveKeyframe(){
  const kf={};
  for(const p of parts)kf[p.id]={x:p.x,y:p.y,rot:p.rot,scale:p.scale,flipX:p.flipX||false,z:p.z,visible:p.visible,role:p.role||'',opacity:p.opacity===undefined?1:p.opacity,locked:!!p.locked,pinX:p.pinX||0,pinY:p.pinY||0,parentId:p.parentId||null,parentOffsetX:p.parentOffsetX||0,parentOffsetY:p.parentOffsetY||0,attachRot:p.attachRot||0,inheritRot:p.inheritRot!==false};
  if(curF>=frames.length){frames.push(kf);curF=frames.length-1;}else frames[curF]=kf;
  drawTL();setStatus('◆ Snímek uložen: '+curF);
}
function applyFrame(f){const kf=frames[f];if(!kf)return;for(const p of parts){if(kf[p.id])Object.assign(p,kf[p.id]);}}
function goTo(f){if(!frames.length)return;curF=Math.max(0,Math.min(frames.length-1,f));applyFrame(curF);draw();drawTL();updateProps();}
document.getElementById('btn-kf').onclick=saveKeyframe;
document.getElementById('btn-addframe').onclick=()=>{saveKeyframe();frames.splice(curF+1,0,JSON.parse(JSON.stringify(frames[curF])));curF++;drawTL();};
document.getElementById('btn-delframe').onclick=()=>{if(frames.length<=1){frames=[];curF=0;}else{frames.splice(curF,1);curF=Math.min(curF,frames.length-1);applyFrame(curF);}draw();drawTL();};
document.getElementById('btn-dupframe').onclick=()=>{if(!frames.length)saveKeyframe();frames.splice(curF+1,0,JSON.parse(JSON.stringify(frames[curF])));curF++;drawTL();};
document.getElementById('btn-clearall').onclick=()=>{frames=[];curF=0;drawTL();setStatus('Časová osa vyčištěná.');};

const TL_ROW=18,TL_LABEL=100,TL_FW=22;
function drawTL(){
  const rows=parts.length,cols=Math.max(frames.length,1);
  TLC.width=Math.max(TL_LABEL+cols*TL_FW+60,document.getElementById('tl-scroll').offsetWidth);
  TLC.height=rows*TL_ROW+22;
  TLX.fillStyle='#151515';TLX.fillRect(0,0,TLC.width,TLC.height);
  TLX.fillStyle='#1e1e1e';TLX.fillRect(0,0,TLC.width,22);
  TLX.font='9px monospace';TLX.textAlign='center';
  for(let f=0;f<cols;f++){const fx=TL_LABEL+f*TL_FW;TLX.strokeStyle='#2a2a2a';TLX.beginPath();TLX.moveTo(fx,0);TLX.lineTo(fx,TLC.height);TLX.stroke();TLX.fillStyle=f===curF?'#ff9f43':'#6f88a8';TLX.fillText(f,fx+TL_FW/2,15);if(frameLabels[f]){TLX.fillStyle='#77baff';TLX.fillText(String(frameLabels[f]).slice(0,3),fx+TL_FW/2,21);}}
  for(let r=0;r<rows;r++){
    const p=parts[r],ry=22+r*TL_ROW;TLX.fillStyle=r%2?'#171717':'#1b1b1b';TLX.fillRect(0,ry,TLC.width,TL_ROW);
    TLX.fillStyle=sel&&sel.id===p.id?'#e87':'#777';TLX.textAlign='left';TLX.fillText(p.name.slice(0,14),8,ry+13);
    for(let f=0;f<frames.length;f++)if(frames[f]&&frames[f][p.id]){const kx=TL_LABEL+f*TL_FW+TL_FW/2,ky=ry+TL_ROW/2;TLX.fillStyle='#e87';TLX.beginPath();TLX.moveTo(kx,ky-4);TLX.lineTo(kx+4,ky);TLX.lineTo(kx,ky+4);TLX.lineTo(kx-4,ky);TLX.closePath();TLX.fill();}
  }
  document.getElementById('tl-info').textContent=`Snímek ${curF}/${Math.max(frames.length-1,0)} (${frames.length} snímků)`;
}
TLC.addEventListener('mousedown',e=>{const r=TLC.getBoundingClientRect(),tx=e.clientX-r.left;if(tx>TL_LABEL){const f=Math.floor((tx-TL_LABEL)/TL_FW);if(f>=0&&f<frames.length)goTo(f);}});

function fileToDataURL(file){return new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=rej;fr.readAsDataURL(file);});}

function cropSelectedPart(){
  if(!sel||!getPartImage(sel)){setStatus('Vyber asset pro oříznutí.');return;}
  const img=getPartImage(sel);const c=document.createElement('canvas');c.width=img.naturalWidth||img.width;c.height=img.naturalHeight||img.height;const ctx=c.getContext('2d');ctx.drawImage(img,0,0);
  const data=ctx.getImageData(0,0,c.width,c.height).data;let minX=c.width,minY=c.height,maxX=-1,maxY=-1;
  for(let y=0;y<c.height;y++){for(let x=0;x<c.width;x++){if(data[(y*c.width+x)*4+3]>10){if(x<minX)minX=x;if(y<minY)minY=y;if(x>maxX)maxX=x;if(y>maxY)maxY=y;}}}
  if(maxX<0){setStatus('Asset je prázdný.');return;}
  const pad=2;minX=Math.max(0,minX-pad);minY=Math.max(0,minY-pad);maxX=Math.min(c.width-1,maxX+pad);maxY=Math.min(c.height-1,maxY+pad);
  const out=document.createElement('canvas');out.width=maxX-minX+1;out.height=maxY-minY+1;out.getContext('2d').drawImage(c,minX,minY,out.width,out.height,0,0,out.width,out.height);
  const im=new Image();im.onload=()=>{sel.img=im;sel.w=out.width;sel.h=out.height;sel.srcData=out.toDataURL('image/png');updateProps();draw();setStatus('Asset oříznutý podle průhlednosti.');};im.src=out.toDataURL('image/png');
}
function startAICropMode(target=sel){
  if(!target||!getPartImage(target)){setStatus('Nejdřív vyber obrázkový asset pro AI ořez.');return;}
  aiCropMode=true; aiCropTarget=target; hideCtxMenu(); selectedIds=new Set([target.id]); sel=target; renderList(); updateProps(); draw();
  setStatus('AI OŘEZ: teď levým tlačítkem táhni obdélník přes oblast assetu, kterou chceš chytře oříznout.');
}
function detectBgColorInRect(data,w,h,x1,y1,x2,y2){
  const pts=[[x1,y1],[x2,y1],[x1,y2],[x2,y2],[Math.floor((x1+x2)/2),y1],[Math.floor((x1+x2)/2),y2],[x1,Math.floor((y1+y2)/2)],[x2,Math.floor((y1+y2)/2)]];
  const samples=[];
  for(const [x,y] of pts){ const xx=Math.max(0,Math.min(w-1,x)), yy=Math.max(0,Math.min(h-1,y)); const i=(yy*w+xx)*4; samples.push([data[i],data[i+1],data[i+2],data[i+3]]); }
  let best=samples[0], bestScore=-1;
  for(const s of samples){ let score=0; for(const t of samples){ const dr=s[0]-t[0], dg=s[1]-t[1], db=s[2]-t[2]; if((dr*dr+dg*dg+db*db)<=30*30)score++; } if(score>bestScore){bestScore=score; best=s;} }
  return {r:best[0],g:best[1],b:best[2],a:best[3]};
}
function findObjectBoundsInRect(img,localRect,tolerance=56){
  const srcW=img.naturalWidth||img.width, srcH=img.naturalHeight||img.height;
  const c=document.createElement('canvas'); c.width=srcW; c.height=srcH; const ctx=c.getContext('2d',{willReadFrequently:true}); ctx.drawImage(img,0,0,srcW,srcH);
  const imd=ctx.getImageData(0,0,srcW,srcH); const d=imd.data;
  let x1=Math.max(0,Math.min(srcW-1,Math.floor(localRect.x1))), y1=Math.max(0,Math.min(srcH-1,Math.floor(localRect.y1)));
  let x2=Math.max(0,Math.min(srcW-1,Math.ceil(localRect.x2))), y2=Math.max(0,Math.min(srcH-1,Math.ceil(localRect.y2)));
  if(x2<=x1||y2<=y1)return null;
  const bg=detectBgColorInRect(d,srcW,srcH,x1,y1,x2,y2), thr=tolerance*tolerance;
  let minX=x2, minY=y2, maxX=-1, maxY=-1;
  for(let y=y1;y<=y2;y++)for(let x=x1;x<=x2;x++){ const i=(y*srcW+x)*4, a=d[i+3]; if(a<8) continue; const dr=d[i]-bg.r,dg=d[i+1]-bg.g,db=d[i+2]-bg.b; if((dr*dr+dg*dg+db*db)>thr || a!==bg.a){ if(x<minX)minX=x; if(y<minY)minY=y; if(x>maxX)maxX=x; if(y>maxY)maxY=y; } }
  if(maxX<0) return {srcW,srcH,bounds:{minX:x1,minY:y1,maxX:x2,maxY:y2}};
  const pad=2; return {srcW,srcH,bounds:{minX:Math.max(0,minX-pad),minY:Math.max(0,minY-pad),maxX:Math.min(srcW-1,maxX+pad),maxY:Math.min(srcH-1,maxY+pad)}};
}
function worldRectToLocalImageRect(part,wx1,wy1,wx2,wy2,img){
  const pts=[worldToLocal(part,wx1,wy1),worldToLocal(part,wx2,wy1),worldToLocal(part,wx2,wy2),worldToLocal(part,wx1,wy2)];
  let minLX=Infinity,minLY=Infinity,maxLX=-Infinity,maxLY=-Infinity; for(const pt of pts){ if(pt.x<minLX)minLX=pt.x; if(pt.y<minLY)minLY=pt.y; if(pt.x>maxLX)maxLX=pt.x; if(pt.y>maxLY)maxLY=pt.y; }
  const srcW=img.naturalWidth||img.width, srcH=img.naturalHeight||img.height; const toSrcX=lx=>((lx+part.w/2)/Math.max(1,part.w))*srcW, toSrcY=ly=>((ly+part.h/2)/Math.max(1,part.h))*srcH;
  return {x1:toSrcX(minLX), y1:toSrcY(minLY), x2:toSrcX(maxLX), y2:toSrcY(maxLY)};
}
async function applyCropToPart(part,bounds,sourceInfo){
  const {srcW,srcH}=sourceInfo, b=bounds; const cropW=Math.max(1,b.maxX-b.minX+1), cropH=Math.max(1,b.maxY-b.minY+1);
  const newDisplayW=part.w*(cropW/srcW), newDisplayH=part.h*(cropH/srcH); const localCx=((b.minX+cropW/2)/srcW)*part.w - part.w/2, localCy=((b.minY+cropH/2)/srcH)*part.h - part.h/2; const worldCenter=localToWorld(part,localCx,localCy);
  if(part.kind==='gif' && part.frames?.length){ const frames=[]; for(const fr of part.frames){ const simg=fr.img; const c=document.createElement('canvas'); c.width=cropW; c.height=cropH; const ctx=c.getContext('2d'); ctx.drawImage(simg,b.minX,b.minY,cropW,cropH,0,0,cropW,cropH); const im=await loadImageURL(c.toDataURL('image/png')); frames.push({img:im}); } part.frames=frames; part.img=frames[0]?.img||part.img; part.srcData=null; }
  else { const img=getPartImage(part); const c=document.createElement('canvas'); c.width=cropW; c.height=cropH; const ctx=c.getContext('2d'); ctx.drawImage(img,b.minX,b.minY,cropW,cropH,0,0,cropW,cropH); const url=c.toDataURL('image/png'); const im=await loadImageURL(url); part.img=im; part.srcData=url; }
  part.w=newDisplayW; part.h=newDisplayH; part.x=worldCenter.x; part.y=worldCenter.y; updateProps(); renderList(); draw(); recordPoseNow(true);
}
async function aiCropPartByRect(part,wx1,wy1,wx2,wy2){
  const img=getPartImage(part); if(!img){setStatus('Vybraný asset nemá obrázek pro AI ořez.');return;} const rect=worldRectToLocalImageRect(part,wx1,wy1,wx2,wy2,img); const sourceInfo=findObjectBoundsInRect(img,rect,56); if(!sourceInfo){setStatus('AI ořez: vybraný obdélník je moc malý.'); return;} await applyCropToPart(part,sourceInfo.bounds,sourceInfo); setStatus('AI OŘEZ hotový. Editor našel objekt odlišný od barvy pozadí a ořízl ho.');
}
const CUSTOM_ASSET_KEY='foxy_custom_assets_v1';'foxy_custom_assets_v1';
function loadCustomAssets(){try{return JSON.parse(localStorage.getItem(CUSTOM_ASSET_KEY)||'[]');}catch(e){return [];}}
function saveCustomAssets(list){try{localStorage.setItem(CUSTOM_ASSET_KEY,JSON.stringify(list));return true;}catch(e){setStatus('LocalStorage je plný. Asset se nepovedlo uložit do lokální knihovny.');return false;}}
async function addFilesToLocalLibrary(files){
  const list=loadCustomAssets();
  for(const file of files){const data=await fileToDataURL(file);const name='local_'+file.name.replace(/\.[^.]+$/,'').replace(/[^a-z0-9_\-]+/gi,'_');list.push({name,category:'custom',path:data,local:true});}
  if(saveCustomAssets(list)){PACK_ASSETS=(EMBEDDED_MANIFEST.assets||[]).concat(list);renderAssetGrid();setStatus('Asset uložený do lokální knihovny pro tento prohlížeč.');}
}

function loadImageURL(url){return new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=rej;im.src=url;});}

document.getElementById('btn-crop-part').onclick=cropSelectedPart;
