document.getElementById('btn-ai-crop-select').onclick=()=>startAICropMode(sel);
document.getElementById('btn-loadlib').onclick=()=>{const inp=document.createElement('input');inp.type='file';inp.accept='image/png,image/jpeg,image/webp';inp.multiple=true;inp.onchange=async e=>addFilesToLocalLibrary(e.target.files);inp.click();};
document.getElementById('btn-load').onclick=()=>{const inp=document.createElement('input');inp.type='file';inp.accept='image/png,image/jpeg,image/webp';inp.multiple=true;inp.onchange=async e=>{for(const file of e.target.files){const data=await fileToDataURL(file);const im=await loadImageURL(data);addImagePart(file.name.replace(/\.[^.]+$/,''),im,'image',{srcData:data});}setStatus('PNG/JPG/WebP načteno.');};inp.click();};

document.getElementById('btn-loadgif').onclick=()=>{const inp=document.createElement('input');inp.type='file';inp.accept='image/gif';inp.onchange=async e=>{
  const file=e.target.files[0];if(!file)return;
  const dataURL=await fileToDataURL(file);
  const im=await loadImageURL(dataURL);
  const p=addImagePart(file.name.replace(/\.[^.]+$/,''),im,'gif',{srcData:dataURL});
  p.frames=[{img:im}];
  startGifRefresh();
  setStatus('GIF načtený. Editor ho průběžně překresluje, takže se má animace hýbat i v náhledu.');
};inp.click();};

