async function serializeProject(){
  const outParts=[];
  for(const p of parts){
    let src=p.srcData||null;
    if(!src&&p.img){const c=document.createElement('canvas');c.width=p.img.naturalWidth||p.img.width;c.height=p.img.naturalHeight||p.img.height;c.getContext('2d').drawImage(p.img,0,0);src=c.toDataURL('image/png');}
    outParts.push({id:p.id,name:p.name,x:p.x,y:p.y,rot:p.rot,scale:p.scale,w:p.w,h:p.h,kind:p.kind,visible:p.visible,z:p.z,flipX:p.flipX,role:p.role||'',category:p.category||'',opacity:p.opacity===undefined?1:p.opacity,locked:!!p.locked,overlayRef:p.overlayRef||'',overlaySide:p.overlaySide||'none',pinX:p.pinX||0,pinY:p.pinY||0,parentId:p.parentId||null,parentOffsetX:p.parentOffsetX||0,parentOffsetY:p.parentOffsetY||0,attachRot:p.attachRot||0,inheritRot:p.inheritRot!==false,text:p.text||'',fontSize:p.fontSize||42,fontFamily:p.fontFamily||'',fontWeight:p.fontWeight||'700',textColor:p.textColor||'#ffffff',srcData:src});
  }
  return {version:'8.5',savedAt:new Date().toISOString(),idCtr,curF,parts:outParts,frames,frameLabels};
}
async function loadProjectData(data){
  parts=[];frames=data.frames||[];frameLabels=data.frameLabels||{};curF=data.curF||0;idCtr=data.idCtr||0;sel=null;
  for(const sp of data.parts||[]){
    let im=null;if(sp.srcData)im=await loadImageURL(sp.srcData);
    const loaded=Object.assign({opacity:1,locked:false,role:'',category:'',overlayRef:'',overlaySide:'none',pinX:0,pinY:0,parentId:null,parentOffsetX:0,parentOffsetY:0,attachRot:0,inheritRot:true,text:'',fontSize:42,fontFamily:'Inter,Segoe UI,Arial,sans-serif',fontWeight:'700',textColor:'#ffffff'},sp,{img:im,frames:null}); if(loaded.kind==='text')measureTextPart(loaded); parts.push(loaded);
  }
  applyFrame(curF);renderList();draw();drawTL();updateProps();setStatus('Projekt načten.');
}
document.getElementById('btn-saveproj').onclick=()=>{document.getElementById('save-name').value='';document.getElementById('modal-save').classList.add('show');};
