document.getElementById('btn-clear-scene').onclick=()=>{parts=[];frames=[];curF=0;sel=null;renderList();updateProps();draw();drawTL();setStatus('Scéna vyčištěná.');};


function computeExportSize(maxW=960,maxH=720){
  const srcW=Math.max(1,Math.round(W||640));
  const srcH=Math.max(1,Math.round(H||420));
  const scale=Math.min(maxW/srcW,maxH/srcH,1);
  return {w:Math.max(1,Math.round(srcW*scale)),h:Math.max(1,Math.round(srcH*scale)),scale};
}
function renderSceneToCanvasCanvas(outW,outH){
  const srcW=Math.max(1,Math.round(W||640));
  const srcH=Math.max(1,Math.round(H||420));
  const c=document.createElement('canvas');
  c.width=Math.max(1,Math.round(outW||srcW));
  c.height=Math.max(1,Math.round(outH||srcH));
  const ctx=c.getContext('2d');
  ctx.save();
  // Důležité: stejný scale pro X i Y. Předtím se X/Y škálovalo zvlášť a postava byla při exportu smrsklá.
  const sc=Math.min(c.width/srcW,c.height/srcH);
  const ox=Math.round((c.width-srcW*sc)/2);
  const oy=Math.round((c.height-srcH*sc)/2);
  ctx.translate(ox,oy);
  ctx.scale(sc,sc);
  draw(ctx,srcW,srcH);
  ctx.restore();
  return c;
}
function restorePartState(saved,savedF){
  for(const st of saved){const p=parts.find(x=>x.id===st.id);if(p)Object.assign(p,st);}
  curF=Math.max(0,Math.min(savedF,Math.max(0,frames.length-1)));
  if(frames.length)applyFrame(curF);
  renderList();updateProps();draw();drawTL();
}

function exportCurrentPNG(){
  if(!parts.length){setStatus('Není co exportovat.');return;}
  if(!frames.length)saveKeyframe();
  const total=Math.max(1,frames.length);
  const expSize=computeExportSize(960,720);
  const ew=expSize.w;
  const eh=expSize.h;
  const cols=Math.min(8,Math.max(1,Math.ceil(Math.sqrt(total))));
  const rows=Math.ceil(total/cols);
  const sheet=document.createElement('canvas');sheet.width=cols*ew;sheet.height=rows*eh;
  const sctx=sheet.getContext('2d');
  const saved=JSON.parse(JSON.stringify(parts.map(p=>({id:p.id,x:p.x,y:p.y,rot:p.rot,scale:p.scale,flipX:p.flipX,z:p.z,visible:p.visible,opacity:p.opacity,locked:p.locked}))));
  const savedF=curF;
  for(let f=0;f<total;f++){
    applyFrame(f);
    const c=renderSceneToCanvasCanvas(ew,eh);
    sctx.drawImage(c,(f%cols)*ew,Math.floor(f/cols)*eh);
  }
  restorePartState(saved,savedF);
  const a=document.createElement('a');a.href=sheet.toDataURL('image/png');a.download='foxy_timeline_vsechny_snimky_'+Date.now()+'.png';a.click();
  setStatus('PNG export hotový bez deformace poměru stran. Počet snímků: '+total+'.');
}
