// ============================================================
// OFFLINE GIF ENCODER — bez CDN, funguje i přes file://
// ============================================================
function _gifWriteShort(arr,v){arr.push(v&255,(v>>8)&255);}
function _gifBitsToBytes(codes,minCodeSize){
  let out=[], cur=0, bits=0, codeSize=minCodeSize+1;
  let clear=1<<minCodeSize, end=clear+1, next=end+1;
  function write(code){
    cur |= code<<bits; bits += codeSize;
    while(bits>=8){out.push(cur&255);cur>>=8;bits-=8;}
  }
  write(clear);
  for(const code of codes){
    write(code);
    next++;
    if(next === (1<<codeSize) && codeSize<12) codeSize++;
    if(next>=4095){write(clear); codeSize=minCodeSize+1; next=end+1;}
  }
  write(end);
  if(bits>0)out.push(cur&255);
  return out;
}
function _gifLzwIndexed(indices,minCodeSize){
  // Robustní režim: žádný chybný slovník. Každý pixel zapisujeme po CLEAR kódu,
  // takže GIF dekodéry nedostanou rozbitá LZW data. Soubor je větší, ale čitelný.
  const clear=1<<minCodeSize, end=clear+1;
  let out=[],cur=0,bits=0,codeSize=minCodeSize+1;
  function write(code){cur|=(code<<bits);bits+=codeSize;while(bits>=8){out.push(cur&255);cur>>=8;bits-=8;}}
  write(clear);
  for(const px of indices){write(px);write(clear);}
  write(end);
  if(bits>0)out.push(cur&255);
  return out;
}
function _gifBlocks(arr,bytes){
  for(let i=0;i<bytes.length;i+=255){
    const chunk=bytes.slice(i,i+255);
    arr.push(chunk.length,...chunk);
  }
  arr.push(0);
}
function _mapToPalette(r,g,b,a){
  // 3-3-2 palette, index 0..255. Bez +1, jinak vznikal neplatný index 256 a rozbitý GIF.
  const ri=r>>5, gi=g>>5, bi=b>>6;
  return ((ri<<5) | (gi<<2) | bi);
}
function _paletteRGB(idx){
  const ri=(idx>>5)&7, gi=(idx>>2)&7, bi=idx&3;
  return [Math.round(ri*255/7),Math.round(gi*255/7),Math.round(bi*255/3)];
}
function makeGifFromCanvases(canvases,delayMs){
  const w=canvases[0].width, h=canvases[0].height;
  const arr=[];
  arr.push(...[...'GIF89a'].map(c=>c.charCodeAt(0)));
  _gifWriteShort(arr,w); _gifWriteShort(arr,h);
  arr.push(0xF7); // global color table 256
  arr.push(0);    // bg index
  arr.push(0);    // aspect
  for(let i=0;i<256;i++){const [r,g,b]=_paletteRGB(i);arr.push(r,g,b);}
  // Netscape loop extension
  arr.push(0x21,0xFF,0x0B,...[...'NETSCAPE2.0'].map(c=>c.charCodeAt(0)),0x03,0x01,0x00,0x00,0x00);
  const delay=Math.max(2,Math.round(delayMs/10));
  for(const canvas of canvases){
    const ctx=canvas.getContext('2d');
    let data;try{data=ctx.getImageData(0,0,w,h).data;}catch(err){throw new Error('GIF export blokuje prohlížeč kvůli file:// obrázkům. Použij tuto verzi s vloženými data assety nebo asset nahraj přes knihovnu. Detail: '+err.message);}
    const idx=[];
    for(let i=0;i<data.length;i+=4)idx.push(_mapToPalette(data[i],data[i+1],data[i+2],data[i+3]));
    // Graphic Control Extension
    arr.push(0x21,0xF9,0x04,0x08); // disposal, bez transparency flagu kvůli artefaktům
    _gifWriteShort(arr,delay);
    arr.push(0x00,0x00); // transparent index nepoužit + terminator
    // Image descriptor
    arr.push(0x2C); _gifWriteShort(arr,0); _gifWriteShort(arr,0); _gifWriteShort(arr,w); _gifWriteShort(arr,h); arr.push(0);
    arr.push(8); // min LZW code size
    const lzw=_gifLzwIndexed(idx,8);
    _gifBlocks(arr,lzw);
  }
  arr.push(0x3B);
  return new Blob([new Uint8Array(arr)],{type:'image/gif'});
}

document.getElementById('btn-export').onclick=async()=>{
  if(!frames.length)saveKeyframe();
  const modal=document.getElementById('modal-export'),msg=document.getElementById('exp-msg'),bar=document.getElementById('export-bar');
  modal.classList.add('show');bar.style.width='0%';msg.textContent='Renderuju snímky offline...';
  const fps=Math.abs(clampFps());
  const expSize=computeExportSize(640,480);
  const ew=expSize.w;
  const eh=expSize.h;
  const canvases=[];
  const saved=JSON.parse(JSON.stringify(parts.map(p=>({id:p.id,x:p.x,y:p.y,rot:p.rot,scale:p.scale,flipX:p.flipX,z:p.z,visible:p.visible}))));
  const savedF=curF;
  for(let f=0;f<frames.length;f++){
    applyFrame(f);
    const c=renderSceneToCanvasCanvas(ew,eh);
    canvases.push(c);
    bar.style.width=Math.round((f+1)/frames.length*70)+'%';
    await new Promise(r=>setTimeout(r,5));
  }
  restorePartState(saved,savedF);
  msg.textContent='Kóduji GIF offline...';bar.style.width='80%';
  let blob;try{blob=makeGifFromCanvases(canvases,Math.round(1000/Math.max(1,fps)));}catch(err){console.error(err);msg.textContent='GIF export selhal: '+err.message;bar.style.width='0%';return;}
  bar.style.width='100%';
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');a.href=url;a.download='foxy_animace_export.gif';a.click();
  msg.textContent='Hotovo. GIF exportovaný bez deformace poměru stran.';
};

