// ============================================================
// RYCHLÝ TUTORIAL — každý krok se drží cca 5 sekund
// ============================================================
const QUICK_TUTORIAL_KEY='foxy_quick_tutorial_seen_8_9';
const qt=document.getElementById('quick-tutorial');
const qtTitle=document.getElementById('qt-title');
const qtText=document.getElementById('qt-text');
const qtCount=document.getElementById('qt-count');
const qtProgress=document.getElementById('qt-progress');
let qtIndex=0,qtTimer=null,qtStart=0,qtRAF=null,qtHighlighted=null;
const QUICK_STEPS=[
  {title:'1) Assety',text:'Vpravo otevři ASSETY. Kliknutím vložíš hlavu, body, ruce, boty, efekty nebo mapu do scény.',target:'#rightbar .tabs',pos:'left'},
  {title:'2) Skládání postavy',text:'Vybraný asset táhni myší po plátně. Kolečkem měníš velikost, Shift + kolečko otáčí. Tlačítka tutorialu už zůstávají nahoře nad plátnem a nepřekryje je animační pozadí.',target:'#canvas-wrap',pos:'top'},
  {title:'3) Role partu',text:'U každé části nastav roli: hlava, tělo, ruka, bota nebo zbraň. Díky tomu funguje správné vrstvení.',target:'#p-role',pos:'right'},
  {title:'4) Vrstvy',text:'Důležité pořadí: boty dole, body nad botami, ruce nad body, hlava nad body, zbraň a efekty nahoře.',target:'#layer-preset',pos:'right'},
  {title:'5) Přesné posuny',text:'Mikroposun 1 / 2 / 5 / 10 px se hodí pro přesné animace. Vyber part a používej šipky v panelu.',target:'#madness-panel',pos:'right'},
  {title:'6) Snímky',text:'Nastav pózu a klikni na SNÍMEK. Pak posuň časovou osu, změň pózu a ulož další snímek.',target:'#timeline',pos:'top'},
  {title:'7) Duch snímků',text:'DUCH SNÍMKŮ zobrazí předchozí a další pozici průhledně. Hodí se pro plynulé ruční animování.',target:'#btn-onion',pos:'top'},
  {title:'8) Mezisnímky',text:'MEZISNÍMKY dopočítají přechod mezi dvěma pózami. Používej je opatrně a pak ručně dolaď.',target:'#btn-tween',pos:'top'},
  {title:'9) Export',text:'EXPORT GIF vyrenderuje timeline do animace. EXPORT PNG uloží všechny snímky časové osy jako sprite sheet.',target:'#btn-export',pos:'top'}
];
function qtClearHighlight(){if(qtHighlighted){qtHighlighted.classList.remove('qt-highlight');qtHighlighted=null;}}
function qtShowStep(i){
  clearTimeout(qtTimer);cancelAnimationFrame(qtRAF);qtClearHighlight();
  qtIndex=Math.max(0,Math.min(QUICK_STEPS.length-1,i));
  const step=QUICK_STEPS[qtIndex];
  qt.className='show '+(step.pos==='top'?'qt-top':step.pos==='left'?'qt-left':step.pos==='right'?'qt-right':'');
  qtTitle.textContent=step.title;qtText.textContent=step.text;qtCount.textContent='Krok '+(qtIndex+1)+'/'+QUICK_STEPS.length+' • každý popis drží 5 sekund';
  const el=document.querySelector(step.target);
  if(el){qtHighlighted=el;el.classList.add('qt-highlight');}
  qtStart=performance.now();
  function anim(now){const p=Math.min(1,(now-qtStart)/5000);qtProgress.style.width=(p*100).toFixed(1)+'%';if(p<1)qtRAF=requestAnimationFrame(anim);}
  qtRAF=requestAnimationFrame(anim);
  qtTimer=setTimeout(()=>{if(qtIndex<QUICK_STEPS.length-1)qtShowStep(qtIndex+1);else qtStop(true);},5000);
}
function qtStartTutorial(force=false){testKeys={};stopPlayback();
  try{if(!force&&localStorage.getItem(QUICK_TUTORIAL_KEY)==='1')return;}catch(e){}
  qt.classList.add('show');qtShowStep(0);
}
function qtStop(markSeen=true){
  clearTimeout(qtTimer);cancelAnimationFrame(qtRAF);qtClearHighlight();qt.className='';qtProgress.style.width='0%';
  if(markSeen){try{localStorage.setItem(QUICK_TUTORIAL_KEY,'1');}catch(e){}}
}
document.getElementById('qt-next').onclick=()=>{if(qtIndex<QUICK_STEPS.length-1)qtShowStep(qtIndex+1);else qtStop(true);};
document.getElementById('qt-prev').onclick=()=>qtShowStep(qtIndex-1);
document.getElementById('qt-skip').onclick=()=>qtStop(true);
document.getElementById('tutorial-run-fast').onclick=()=>{document.getElementById('modal-tutorial').classList.remove('show');qtStartTutorial(true);};



function getSelectedParts(){
  const arr=parts.filter(p=>selectedIds.has(p.id));
  if(arr.length)return arr;
  if(sel)return [sel];
  return [];
}
function selectAllParts(){selectedIds=new Set(parts.map(p=>p.id));allSelected=false;sel=null;renderList();updateProps();draw();setStatus('Označené všechny části. Pravým tlačítkem zvol Složit, nebo táhni výběrový obdélník.');}
function partWorldBounds(p){
  const scale=Math.max(0.0001,Math.abs(p.scale||1));
  const hw=(p.w||1)*scale/2, hh=(p.h||1)*scale/2;
  const rot=p.rot||0, c=Math.cos(rot), s=Math.sin(rot);
  const corners=[[-hw,-hh],[hw,-hh],[hw,hh],[-hw,hh]];
  let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;
  for(const [x,y] of corners){ const wx=p.x + x*c - y*s; const wy=p.y + x*s + y*c; if(wx<minX)minX=wx; if(wx>maxX)maxX=wx; if(wy<minY)minY=wy; if(wy>maxY)maxY=wy; }
  return {minX,minY,maxX,maxY};
}
function boundsForParts(list){
  let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;
  for(const p of list){ const b=partWorldBounds(p); minX=Math.min(minX,b.minX); maxX=Math.max(maxX,b.maxX); minY=Math.min(minY,b.minY); maxY=Math.max(maxY,b.maxY); }
  if(!isFinite(minX)) return {minX:0,minY:0,maxX:1,maxY:1,w:1,h:1,cx:.5,cy:.5};
  return {minX,minY,maxX,maxY,w:Math.max(1,maxX-minX),h:Math.max(1,maxY-minY),cx:(minX+maxX)/2,cy:(minY+maxY)/2};
}
function groupSelectedParts(){
  const list=getSelectedParts(); if(!list.length){setStatus('Nejdřív označ části pro složení.');return;} stopPlayback();
  const b=boundsForParts(list), pad=24; const c=document.createElement('canvas'); c.width=Math.max(1,Math.ceil(b.w+pad*2)); c.height=Math.max(1,Math.ceil(b.h+pad*2)); const ctx=c.getContext('2d');
  const ids=new Set(list.map(p=>p.id)); for(const p of sortedParts()){ if(ids.has(p.id)) drawPartToCtx(ctx,p,b.minX-pad,b.minY-pad); }
  const data=c.toDataURL('image/png'); const im=new Image();
  im.onload=()=>{ const children=list.map(ch=>Object.assign({},ch,{localX:ch.x-b.cx,localY:ch.y-b.cy,origId:ch.id})); const group={id:++idCtr,name:'slozeny_asset',x:b.cx,y:b.cy,rot:0,scale:1,w:c.width,h:c.height,img:im,kind:'image',visible:true,z:Math.max(...list.map(p=>p.z))+1,flipX:false,srcData:data,role:'group',opacity:1,locked:false,children,overlayRef:'',overlaySide:'none',pinX:0,pinY:0,parentId:null,parentOffsetX:0,parentOffsetY:0,attachRot:0,inheritRot:true}; parts=parts.filter(p=>!ids.has(p.id)); parts.push(group); selectedIds=new Set([group.id]); selectPart(group); drawTL(); recordPoseNow(true); setStatus('Vybrané části složené do jednoho assetu. Oprava: složení teď počítá i rotaci, takže meč už nemá mizet.'); };
  im.src=data;
}
function colorDistSq(r1,g1,b1,r2,g2,b2){const dr=r1-r2,dg=g1-g2,db=b1-b2;return dr*dr+dg*dg+db*db;}
function detectLikelyBgColor(data,w,h){
  const pts=[[0,0],[w-1,0],[0,h-1],[w-1,h-1],[Math.floor(w/2),0],[Math.floor(w/2),h-1],[0,Math.floor(h/2)],[w-1,Math.floor(h/2)]];
  const samples=[]; for(const [x,y] of pts){const i=(y*w+x)*4;samples.push([data[i],data[i+1],data[i+2],data[i+3]]);} let best=samples[0],bestScore=-1;
  for(const s of samples){let score=0; for(const t of samples){ if(colorDistSq(s[0],s[1],s[2],t[0],t[1],t[2])<=32*32)score++; } if(score>bestScore){bestScore=score; best=s;} }
  return {r:best[0],g:best[1],b:best[2],a:best[3]};
}
function smartRemoveBgFromImage(img,tolerance=58){
  const w=img.naturalWidth||img.width,h=img.naturalHeight||img.height; const c=document.createElement('canvas'); c.width=w; c.height=h; const ctx=c.getContext('2d',{willReadFrequently:true}); ctx.drawImage(img,0,0,w,h); const imd=ctx.getImageData(0,0,w,h); const d=imd.data; const bg=detectLikelyBgColor(d,w,h); const thr=tolerance*tolerance; const visited=new Uint8Array(w*h); const q=new Uint32Array(w*h); let qs=0,qe=0;
  function tryPush(x,y){ if(x<0||y<0||x>=w||y>=h)return; const idx=y*w+x; if(visited[idx])return; const di=idx*4; if(d[di+3]===0)return; if(colorDistSq(d[di],d[di+1],d[di+2],bg.r,bg.g,bg.b)<=thr){visited[idx]=1; q[qe++]=idx;} }
  for(let x=0;x<w;x++){tryPush(x,0); tryPush(x,h-1);} for(let y=0;y<h;y++){tryPush(0,y); tryPush(w-1,y);} while(qs<qe){const idx=q[qs++]; const di=idx*4; d[di+3]=0; const x=idx%w,y=(idx/w)|0; tryPush(x+1,y); tryPush(x-1,y); tryPush(x,y+1); tryPush(x,y-1);} ctx.putImageData(imd,0,0); return c.toDataURL('image/png');
}
async function smartRemoveBgSelected(){
  if(!sel){setStatus('Nejdřív vyber asset, u kterého chceš smazat pozadí.');return;} if(sel.kind==='text'){setStatus('Textový asset pozadí nemá.');return;}
  if(sel.kind==='gif' && sel.frames?.length){ const newFrames=[]; for(const fr of sel.frames){ const url=smartRemoveBgFromImage(fr.img,58); const im=await loadImageURL(url); newFrames.push({img:im}); } sel.frames=newFrames; sel.img=newFrames[0]?.img||sel.img; sel.srcData=smartRemoveBgFromImage(sel.img,58); draw(); renderList(); updateProps(); recordPoseNow(true); setStatus('Chytré AI mazání pozadí hotové pro GIF.'); return; }
  const source=sel.img; if(!source){setStatus('Vybraný asset nemá obrázek.');return;} const url=smartRemoveBgFromImage(source,58); const im=await loadImageURL(url); sel.img=im; sel.srcData=url; draw(); renderList(); updateProps(); recordPoseNow(true); setStatus('Chytré AI mazání pozadí hotové. Jednobarevné pozadí od krajů bylo odstraněné.');
}
function ungroupSelected(){
  const target=(sel&&sel.children)?sel:getSelectedParts().find(p=>p.children); if(!target||!target.children){setStatus('Vyber složený asset, který chceš rozložit.');return;}
  const c=Math.cos(target.rot),s=Math.sin(target.rot); const restored=target.children.map(ch=>{ const p=Object.assign({},ch,{id:++idCtr}); const lx=(ch.localX??0)*target.scale,ly=(ch.localY??0)*target.scale; p.x=target.x+lx*c-ly*s; p.y=target.y+lx*s+ly*c; p.rot=(ch.rot||0)+target.rot; p.scale=(ch.scale||1)*target.scale; delete p.localX; delete p.localY; return p; });
  parts=parts.filter(p=>p!==target); parts.push(...restored); selectedIds=new Set(restored.map(p=>p.id)); sel=null; renderList(); updateProps(); draw(); drawTL(); recordPoseNow(true); setStatus('Složený asset rozložený zpět na původní části.');
}
function showCtxMenu(x,y,target){
  const menu=document.getElementById('ctx-menu');if(!menu)return;
  document.getElementById('ctx-title').textContent=target?('Vybráno: '+target.name):'Akce výběru';
  document.getElementById('ctx-replace').disabled=!target;
  document.getElementById('ctx-ungroup').disabled=!(target&&target.children);
  document.getElementById('ctx-decompose').disabled=!target;
  document.getElementById('ctx-smart-bg-remove').disabled=!target;
  document.getElementById('ctx-ai-crop').disabled=!target;
  document.getElementById('ctx-attach-handL').disabled=!target;
  document.getElementById('ctx-attach-handR').disabled=!target;
  document.getElementById('ctx-detach').disabled=!(target&&target.parentId);
  menu.style.left=Math.min(x,window.innerWidth-230)+'px';menu.style.top=Math.min(y,window.innerHeight-260)+'px';menu.classList.add('show');
}
function hideCtxMenu(){document.getElementById('ctx-menu')?.classList.remove('show');}
document.addEventListener('click',e=>{if(!e.target.closest('#ctx-menu'))hideCtxMenu();});
document.getElementById('ctx-replace').onclick=()=>{hideCtxMenu();if(!sel){setStatus('Nejdřív vyber asset na plátně.');return;}replaceMode=true;document.body.classList.add('replace-mode');document.querySelector('.tab[data-tab="assets"]')?.click();setStatus('Režim výměny: klikni na asset v knihovně. Pozice, rotace a velikost zůstanou.');};
