document.getElementById('ctx-ai-crop').onclick=()=>{hideCtxMenu();startAICropMode(sel);};
document.getElementById('ctx-attach-handL').onclick=()=>{hideCtxMenu();attachSelectedToRole('handL');};
document.getElementById('ctx-attach-handR').onclick=()=>{hideCtxMenu();attachSelectedToRole('handR');};
document.getElementById('ctx-detach').onclick=()=>{hideCtxMenu();detachSelectedParent();};
document.getElementById('ctx-compose').onclick=()=>{hideCtxMenu();composeMode=true;selectedIds=new Set();sel=null;document.body.classList.add('compose-mode');document.querySelector('.tab[data-tab="parts"]')?.click();setStatus('SLOŽIT: levým tlačítkem táhni obdélník přes části, které chceš spojit.');};
document.getElementById('ctx-ungroup').onclick=()=>{hideCtxMenu();ungroupSelected();};
document.getElementById('ctx-dup').onclick=()=>{hideCtxMenu();duplicateSelectedParts();};
document.getElementById('ctx-top').onclick=()=>{hideCtxMenu();for(const p of getSelectedParts())p.z=Math.max(...parts.map(x=>x.z))+1;renderList();draw();setStatus('Vybrané části poslané nahoru.');};
document.getElementById('ctx-lock').onclick=()=>{hideCtxMenu();for(const p of getSelectedParts())p.locked=!p.locked;renderList();updateProps();draw();setStatus('Zámek vybraných částí přepnutý.');};
function duplicateSelectedParts(){const list=getSelectedParts();if(!list.length){duplicatePart();return;}const copies=[];for(const p of list){const copy=Object.assign({},p,{id:++idCtr,name:p.name+'_copy',x:p.x+18,y:p.y+18,z:p.z+1,img:p.img,frames:p.frames||null,children:p.children?JSON.parse(JSON.stringify(p.children)):undefined});parts.push(copy);copies.push(copy);}selectedIds=new Set(copies.map(p=>p.id));sel=copies.length===1?copies[0]:null;renderList();updateProps();draw();drawTL();setStatus('Vybrané části duplikované.');}
document.getElementById('btn-select-all').onclick=selectAllParts;
document.getElementById('btn-min-tools').onclick=()=>{const on=document.body.classList.toggle('tools-min');document.getElementById('btn-min-tools').textContent=on?'ZOBRAZIT NÁSTROJE':'MINIMALIZOVAT';setTimeout(()=>{resize();draw();},60);};

function currentPose(){
  const pose={};
  for(const p of parts)pose[p.id]={x:p.x,y:p.y,rot:p.rot,scale:p.scale,flipX:p.flipX||false,z:p.z,visible:p.visible,role:p.role||'',opacity:p.opacity===undefined?1:p.opacity,locked:!!p.locked,pinX:p.pinX||0,pinY:p.pinY||0,parentId:p.parentId||null,parentOffsetX:p.parentOffsetX||0,parentOffsetY:p.parentOffsetY||0,attachRot:p.attachRot||0,inheritRot:p.inheritRot!==false};
  return pose;
}
function applyPose(pose){
  for(const p of parts){if(pose[p.id])Object.assign(p,pose[p.id]);}
  draw();updateProps();drawTL();
}
function lerp(a,b,t){return a+(b-a)*t;}
function interpPose(a,b,t){
  const out={};
  for(const p of parts){
    const A=a[p.id]||{},B=b[p.id]||A;
    out[p.id]={
      x:lerp(A.x??p.x,B.x??p.x,t),
      y:lerp(A.y??p.y,B.y??p.y,t),
      rot:lerp(A.rot??p.rot,B.rot??p.rot,t),
      scale:lerp(A.scale??p.scale,B.scale??p.scale,t),
      flipX:t<.5?(A.flipX??p.flipX):(B.flipX??p.flipX),
      z:B.z??A.z??p.z,
      visible:B.visible??A.visible??p.visible,
      opacity:B.opacity??A.opacity??p.opacity??1,
      locked:B.locked??A.locked??p.locked??false
    };
  }
  return out;
}
document.getElementById('btn-onion').onclick=()=>{onion=!onion;document.getElementById('btn-onion').classList.toggle('active',onion);draw();setStatus(onion?'DUCH SNÍMKŮ zapnutý.':'DUCH SNÍMKŮ vypnutý.');};
document.getElementById('btn-pingpong').onclick=()=>{pingpong=!pingpong;document.getElementById('btn-pingpong').classList.toggle('active',pingpong);setStatus(pingpong?'TAM/ZPĚT zapnutý.':'TAM/ZPĚT vypnutý.');};
document.getElementById('btn-copypose').onclick=()=>{copiedPose=currentPose();setStatus('Póza zkopírovaná.');};
document.getElementById('btn-pastepose').onclick=()=>{if(!copiedPose){setStatus('Není zkopírovaná žádná póza.');return;}applyPose(copiedPose);saveKeyframe();setStatus('Póza vložená a uložená jako snímek.');};
document.getElementById('btn-tween').onclick=()=>{
  if(frames.length<2){setStatus('Mezisnímky potřebují aspoň 2 snímky.');return;}
  const a=frames[curF], b=frames[Math.min(curF+1,frames.length-1)];
  if(!a||!b||curF>=frames.length-1){setStatus('Není další snímek pro mezisnímky.');return;}
  const count=parseInt(document.getElementById('tween-count')?.value||'2',10);
  const inserted=[];
  for(let i=1;i<=count;i++)inserted.push(interpPose(a,b,i/(count+1)));
  frames.splice(curF+1,0,...inserted);
  drawTL();setStatus('Vloženo '+count+' mezisnímků mezi snímky '+curF+' a '+(curF+count+1)+'.');
};
// Automatické generátory chůze/útoku byly odstraněné. Animace se skládá ručně přes snímky, pózy a mezisnímky.

function markFrame(label){
  if(!frames.length)saveKeyframe();
  frameLabels[curF]=label;
  drawTL();setStatus('Snímek '+curF+' označen jako: '+label+'.');
}
function holdFrame(){
  if(!frames.length)saveKeyframe();
  const copy=JSON.parse(JSON.stringify(frames[curF]));
  frames.splice(curF+1,0,copy);
  curF++;
  drawTL();setStatus('Přidaný držící snímek. Animace se na póze chvíli zastaví.');
}
function propagateSelectedPartToAllFrames(){
  if(!sel){setStatus('Vyber part, který chceš propsat do všech snímků.');return;}
  if(!frames.length)saveKeyframe();
  const data={x:sel.x,y:sel.y,rot:sel.rot,scale:sel.scale,flipX:!!sel.flipX,z:sel.z,visible:sel.visible,role:sel.role||'',opacity:sel.opacity===undefined?1:sel.opacity,locked:!!sel.locked};
  for(const fr of frames)fr[sel.id]=Object.assign({},fr[sel.id]||{},data);
  drawTL();setStatus('Vybraný part propsaný do všech snímků.');
}
function copyZLayersToAllFrames(){
  if(!frames.length)saveKeyframe();
  for(const fr of frames){for(const p of parts){fr[p.id]=Object.assign({},fr[p.id]||{}, {z:p.z, role:p.role||''});}}
  drawTL();setStatus('Z-vrstvy propsané do všech snímků.');
}
function freezeSelectedPart(){if(!sel){setStatus('Vyber part.');return;}sel.locked=true;updateProps();renderList();draw();setStatus('Part zamčený pro přesné pózování.');}
function unfreezeAll(){for(const p of parts)p.locked=false;updateProps();renderList();draw();setStatus('Všechny party odemčené.');}
function alignSelected(axis){
  if(!sel){setStatus('Vyber part, podle kterého se má srovnávat.');return;}
  for(const p of parts){if(p!==sel&&!p.locked){if(axis==='x')p.x=sel.x;else p.y=sel.y;}}
  draw();updateProps();setStatus(axis==='x'?'Party srovnané podle X.':'Party srovnané podle Y.');
}
function cleanHiddenParts(){const before=parts.length;parts=parts.filter(p=>p.visible!==false);if(sel&&!parts.includes(sel))sel=null;renderList();updateProps();draw();drawTL();setStatus('Smazané skryté party: '+(before-parts.length));}
function nudgeSelected(dx,dy){if(!sel||sel.locked){setStatus('Vyber odemčený part.');return;}sel.x+=dx;sel.y+=dy;updateProps();draw();}
function insertFrameBefore(){const pose=currentPose();frames.splice(curF,0,pose);drawTL();setStatus('Snímek vložen před aktuální.');}
function goPrevFrame(){if(frames.length)goTo(curF-1);}
function goNextFrame(){if(frames.length)goTo(curF+1);}
document.getElementById('mk-neutral').onclick=()=>markFrame('KLID');
document.getElementById('mk-extreme').onclick=()=>markFrame('EXT');
document.getElementById('mk-impact').onclick=()=>markFrame('DOPAD');
document.getElementById('mk-recoil').onclick=()=>markFrame('RÁZ');
document.getElementById('btn-freeze-part').onclick=freezeSelectedPart;
document.getElementById('btn-unfreeze-all').onclick=unfreezeAll;
document.getElementById('btn-align-x').onclick=()=>alignSelected('x');
document.getElementById('btn-align-y').onclick=()=>alignSelected('y');
document.getElementById('btn-copy-z').onclick=copyZLayersToAllFrames;
document.getElementById('btn-clean-hidden').onclick=cleanHiddenParts;
document.getElementById('btn-holdframe').onclick=holdFrame;
document.getElementById('btn-prop-part').onclick=propagateSelectedPartToAllFrames;
document.getElementById('btn-prevframe').onclick=goPrevFrame;
document.getElementById('btn-nextframe').onclick=goNextFrame;
document.getElementById('btn-insert-before').onclick=insertFrameBefore;
for(const [id,dx,dy] of [['btn-nudge-left',-1,0],['btn-nudge-right',1,0],['btn-nudge-up',0,-1],['btn-nudge-down',0,1]]){
  const el=document.getElementById(id); if(el)el.onclick=()=>{const step=parseInt(document.getElementById('nudge-step')?.value||'5',10);nudgeSelected(dx*step,dy*step);};
}

function stopTestLoop(){}
let testKeys={};



function mirrorPose(){
  if(!parts.length)return;
  const cx=W/2;
  for(const p of parts){p.x=cx-(p.x-cx);p.flipX=!p.flipX;p.rot=-p.rot;}
  updateProps();draw();setStatus('Aktuální póza zrcadlená.');
}
function reverseTimeline(){
  if(frames.length<2){setStatus('Časová osa nemá co otočit.');return;}
  frames.reverse();curF=frames.length-1-curF;applyFrame(curF);drawTL();setStatus('Časová osa otočená pozpátku.');
}
document.getElementById('btn-mirrorpose').onclick=mirrorPose;
document.getElementById('btn-reverse').onclick=reverseTimeline;

document.addEventListener('keydown',e=>{
  if(e.target.tagName==='INPUT'||e.target.tagName==='TEXTAREA'||e.target.tagName==='SELECT')return;
  if(e.key==='v'||e.key==='V')setTool('select');
  if(e.key==='r'||e.key==='R')setTool('rotate');
  if(e.key==='s'||e.key==='S')setTool('scale');
  if(e.key==='k'||e.key==='K')saveKeyframe();
  if(e.key==='o'||e.key==='O')document.getElementById('btn-onion').click();
  if(e.key==='p'||e.key==='P')document.getElementById('btn-pingpong').click();
  if(e.key==='t'||e.key==='T')document.getElementById('btn-tween').click();
  if(e.key==='h'||e.key==='H')holdFrame();
  if(e.key===' '){e.preventDefault();document.getElementById('btn-play').click();}
  if(!sel&&e.key==='ArrowRight'){e.preventDefault();goTo(curF+1);}
  if(!sel&&e.key==='ArrowLeft'){e.preventDefault();goTo(curF-1);}
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();duplicatePart();}
  if(sel&&!sel.locked&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const step=e.shiftKey?10:1;if(e.key==='ArrowUp')sel.y-=step;if(e.key==='ArrowDown')sel.y+=step;if(e.key==='ArrowLeft')sel.x-=step;if(e.key==='ArrowRight')sel.x+=step;updateProps();draw();}
  if(sel&&(e.key==='['||e.key===']')){e.preventDefault();moveLayer(e.key===']'?1:-1);}
  if(sel&&!sel.locked&&(e.key==='+'||e.key==='='||e.key==='-')){e.preventDefault();sel.scale=Math.max(.03,sel.scale+(e.key==='-'?-.05:.05));updateProps();draw();}
  if(sel&&!sel.locked&&(e.key==='q'||e.key==='Q'||e.key==='e'||e.key==='E')){e.preventDefault();sel.rot+=(e.key.toLowerCase()==='e'?0.05:-0.05);updateProps();draw();}
  if(e.key==='Delete'||e.key==='Backspace')delPart();
});

