let PACK_ASSETS=[];
async function loadPackManifest(){
  PACK_ASSETS=(EMBEDDED_MANIFEST.assets||[]).filter(a=>!String(a.path||'').includes('krev_')&&!String(a.name||'').includes('blood_')).concat(loadCustomAssets());
  renderAssetGrid();
}
let replaceMode=false;
function replaceSelectedWithAsset(a,im){
  if(!sel){setStatus('Nejdřív vyber asset, který chceš změnit.');return;}
  const old={x:sel.x,y:sel.y,rot:sel.rot,scale:sel.scale,z:sel.z,flipX:sel.flipX,role:sel.role,opacity:sel.opacity,locked:sel.locked,pinX:sel.pinX,pinY:sel.pinY,parentId:sel.parentId,parentOffsetX:sel.parentOffsetX,parentOffsetY:sel.parentOffsetY,attachRot:sel.attachRot,inheritRot:sel.inheritRot};
  sel.name=a.name||sel.name;sel.img=im;sel.kind='image';sel.frames=null;sel.w=im.width;sel.h=im.height;
  const maxH=120, ratio=im.width/Math.max(1,im.height); if(sel.h>maxH){sel.h=maxH;sel.w=maxH*ratio;}
  Object.assign(sel,old);sel.category=a.category||sel.category||'';
  updateProps();renderList();draw();recordPoseNow(true);
  replaceMode=false;document.body.classList.remove('replace-mode');
  setStatus('Asset vyměněný. Transformace zůstala stejná.');
}
function renderAssetGrid(){
  const grid=document.getElementById('asset-grid');
  const filterEl=document.getElementById('asset-filter');
  const filter=filterEl?filterEl.value:'all';
  grid.innerHTML='';
  const searchEl=document.getElementById('asset-search');
  const q=(searchEl&&searchEl.value||'').toLowerCase().trim();
  const list=PACK_ASSETS.filter(a=>(filter==='all'||a.category===filter) && (!q || (a.name||'').toLowerCase().includes(q) || (a.path||'').toLowerCase().includes(q)));
  if(!list.length){grid.innerHTML='<div class="small-note">V této kategorii nejsou žádné assety — vše bylo smazané.</div>';return;}
  for(const a of list){
    const card=document.createElement('div');card.className='asset-card';
    const img=document.createElement('img');img.src=a.path;
    const nm=document.createElement('div');nm.className='aname';nm.textContent=a.name||a.path.split('/').pop();
    card.appendChild(img);card.appendChild(nm);
    card.draggable=true;
    card.title='Klik = vložit. Pravý klik = nahradit vybraný. Táhni na plátno = vložit přesně.';
    card.addEventListener('dragstart',e=>{stopPlayback();e.dataTransfer.effectAllowed='copy';e.dataTransfer.setData('application/x-foxy-asset',JSON.stringify(a));e.dataTransfer.setData('text/plain',a.path||a.name||'');setStatus('Táhni asset na plátno a pusť ho tam, kam ho chceš vložit.');});
    card.onclick=async()=>{if((a.category||'')==='mapy'){setStatus('Mapy se už nepoužívají, TEST 2D byl odstraněný.');return;}const im=await loadImageURL(a.path);if(replaceMode&&sel){replaceSelectedWithAsset(a,im);return;}addImagePart(a.name||a.path.split('/').pop().replace(/\.[^.]+$/,''),im,'image',{srcData:null,category:a.category||''});};
    card.oncontextmenu=async e=>{e.preventDefault();if(!sel){setStatus('Vyber asset na plátně, pak pravým klikem na asset v knihovně ho vyměníš.');return;}const im=await loadImageURL(a.path);replaceSelectedWithAsset(a,im);};
    grid.appendChild(card);
  }
}

const iconSizeEl=document.getElementById('icon-size');
const iconSizeVal=document.getElementById('icon-size-val');
function applyIconSize(v){document.documentElement.style.setProperty('--asset-card-h',v+'px');document.documentElement.style.setProperty('--asset-img',Math.round(v*.77)+'px');if(iconSizeVal)iconSizeVal.textContent=v;}
if(iconSizeEl){iconSizeEl.oninput=e=>applyIconSize(e.target.value);applyIconSize(iconSizeEl.value);}
const sortBtn=document.getElementById('btn-sort-assets');if(sortBtn)sortBtn.onclick=()=>{PACK_ASSETS.sort((a,b)=>(a.category+a.name).localeCompare(b.category+b.name));renderAssetGrid();setStatus('Assety seřazené.');};
const randomBtn=document.getElementById('btn-random-asset');if(randomBtn)randomBtn.onclick=async()=>{const filter=document.getElementById('asset-filter')?.value||'all';const list=PACK_ASSETS.filter(a=>filter==='all'||a.category===filter);if(!list.length)return;const a=list[Math.floor(Math.random()*list.length)];const im=await loadImageURL(a.path);addImagePart(a.name||a.path.split('/').pop().replace(/\.[^.]+$/,''),im,'image',{srcData:null,category:a.category||''});setStatus('Vložen náhodný asset: '+(a.name||a.path));};

const assetFilterEl=document.getElementById('asset-filter');
if(assetFilterEl)assetFilterEl.onchange=renderAssetGrid;
const assetSearchEl=document.getElementById('asset-search');
if(assetSearchEl)assetSearchEl.oninput=renderAssetGrid;


// ============================================================
// 8.8 TAŽNÉ HRANY PANELŮ — pravý panel + spodní časová osa
// ============================================================
function initResizablePanels(){
  const right=document.getElementById('rightbar');
  const rx=document.getElementById('right-resizer');
  const tl=document.getElementById('timeline');
  const ty=document.getElementById('timeline-resizer');
  const zoom=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--ui-zoom'))||0.8;
  const savedW=parseInt(safeStorageGet('foxy_editor_rightbar_w_8_9')||'',10);
  const savedH=parseInt(safeStorageGet('foxy_editor_timeline_h_8_9')||'',10);
  if(savedW)right.style.width=Math.max(240,Math.min(760,savedW))+'px';
  if(savedH)tl.style.height=Math.max(100,Math.min(520,savedH))+'px';
  if(rx)rx.addEventListener('mousedown',e=>{
    e.preventDefault();document.body.classList.add('resizing-panel','resizing-x');
    function move(ev){const cssX=ev.clientX/zoom;const appW=window.innerWidth/zoom;const w=Math.max(240,Math.min(760,appW-cssX));right.style.width=w+'px';resize();drawTL();safeStorageSet('foxy_editor_rightbar_w_8_9',String(Math.round(w)));}
    function up(){document.body.classList.remove('resizing-panel','resizing-x');window.removeEventListener('mousemove',move);window.removeEventListener('mouseup',up);}
    window.addEventListener('mousemove',move);window.addEventListener('mouseup',up);
  });
  if(ty)ty.addEventListener('mousedown',e=>{
    e.preventDefault();document.body.classList.add('resizing-panel','resizing-y');
    const startY=e.clientY/zoom,startH=tl.offsetHeight;
    function move(ev){const y=ev.clientY/zoom;const h=Math.max(100,Math.min(520,startH-(y-startY)));tl.style.height=h+'px';resize();drawTL();safeStorageSet('foxy_editor_timeline_h_8_9',String(Math.round(h)));}
    function up(){document.body.classList.remove('resizing-panel','resizing-y');window.removeEventListener('mousemove',move);window.removeEventListener('mouseup',up);}
    window.addEventListener('mousemove',move);window.addEventListener('mouseup',up);
  });
}
initResizablePanels();

resize();drawTL();loadPackManifest();setTool('select');setStatus('Foxy editor 10.1 připravený. GIF/PNG export drží stejný poměr stran jako editor, takže assety nejsou smrsklé.');
setupFoxyChat();
setTimeout(()=>{try{if(localStorage.getItem(QUICK_TUTORIAL_KEY)!=='1')qtStartTutorial(false);else document.getElementById('modal-news').classList.add('show');}catch(e){qtStartTutorial(true);}},500);
